export const meta = {
  name: 'prh-codebase-analysis',
  description: '全面分析公租房监测系统：文档、本体XML、模型、页面、git改动，并建立 快照/事实→设计表→页面 映射',
  phases: [
    { title: '读文档与模型', detail: '并行读 3 份需求/对齐/交接文档 + 2 份模型指南 + README' },
    { title: '读本体XML', detail: '解析 prh.xml 实体表/快照事实/枚举 + 平台层 6 个 XML' },
    { title: '读原型与前端', detail: '解析 HTML 原型工作台 + 页面/路由/服务层' },
    { title: '读git改动', detail: '分析最近 6 条提交的设计意图与演进方向' },
    { title: '综合映射', detail: '建立 快照事实→dataSet设计表→页面 三方对照与缺口分析' },
  ],
}

const ROOT = 'D:/work/housing-occupancy-inspection'

// ---------- Phase 1: docs + model guides (parallel) ----------
phase('读文档与模型')

const DOC_SCHEMA = {
  type: 'object',
  required: ['title', 'purpose', 'keyPoints', 'entitiesOrTables', 'pagesOrFeatures', 'openQuestions'],
  properties: {
    title: { type: 'string' },
    purpose: { type: 'string', description: '文档目的，一句话' },
    keyPoints: { type: 'array', items: { type: 'string' }, description: '8-15 条最重要的内容要点（中文）' },
    entitiesOrTables: { type: 'array', items: { type: 'string' }, description: '文档中提到的实体/表/数据对象名' },
    pagesOrFeatures: { type: 'array', items: { type: 'string' }, description: '文档中提到的页面/功能模块' },
    businessRules: { type: 'array', items: { type: 'string' }, description: '业务规则/校验/审批流要点' },
    openQuestions: { type: 'array', items: { type: 'string' }, description: '文档中标注的待办/疑问/缺口/TODO' },
  },
}

const docs = await parallel([
  () => agent(`阅读文件 ${ROOT}/公租房保障居住状况动态监测系统需求设计文档.md（约326行，全部读完）。这是系统的原始需求设计文档。提炼：系统目标、业务范围、涉及的实体/数据对象、页面/功能模块、关键业务规则（资格、考勤、预警、审批、退出等）、以及任何标注的待办或开放问题。用中文。`, { schema: DOC_SCHEMA, phase: '读文档与模型', label: '需求设计文档' }),
  () => agent(`阅读文件 ${ROOT}/本体与需求对齐分析报告.md（约232行，全部读完）。这是把本体模型与需求对照的分析报告。提炼：对齐结论、已覆盖/未覆盖的需求点、本体与需求之间的差异和缺口、建议改动。entitiesOrTables 填涉及的本体实体，openQuestions 填未对齐项。用中文。`, { schema: DOC_SCHEMA, phase: '读文档与模型', label: '对齐分析报告' }),
  () => agent(`阅读文件 ${ROOT}/本体改动集-交接本体团队.md（约405行，全部读完）。这是交接给本体团队的改动清单。提炼：每一项要本体团队做的改动（新增/修改/删除哪些实体、属性、枚举、快照事实、动作、规则）、改动原因、优先级。entitiesOrTables 填受影响实体，businessRules 填涉及的规则/动作改动，openQuestions 填仍待确认项。用中文。`, { schema: DOC_SCHEMA, phase: '读文档与模型', label: '本体改动集' }),
  () => agent(`阅读这三个文件：${ROOT}/README.md、${ROOT}/model/model/typescript/docs/model-reference.md（1350行）、${ROOT}/model/model/typescript/docs/action-usage-guide.md（1016行）。这两份是"字节觉醒"本体平台的模型参考与动作（Action/OQL）使用指南。提炼：本体平台的核心概念（ontology/class/dataSet/SEMANTIC_MODEL/fact/action/businessRule/datasource/OQL查询）、kind 与 isPersistent 的含义、快照事实(SEMANTIC_MODEL)如何定义和查询、Action 的执行规则/前后置/校验机制。这是理解 prh.xml 的关键背景。用中文，keyPoints 给 12-18 条。`, { schema: DOC_SCHEMA, phase: '读文档与模型', label: '平台模型指南' }),
])

// ---------- Phase 2: ontology XML ----------
phase('读本体XML')

const ONTOLOGY_SCHEMA = {
  type: 'object',
  required: ['entityClasses', 'snapshotFacts', 'enums', 'summary'],
  properties: {
    summary: { type: 'string', description: '整体结构概述（中文）' },
    entityClasses: {
      type: 'array',
      description: '所有 isPersistent 的持久化实体 class（22个）',
      items: {
        type: 'object',
        required: ['name', 'title', 'dataSet'],
        properties: {
          name: { type: 'string' },
          title: { type: 'string' },
          dataSet: { type: 'string', description: '物理设计表名，如 prh_resident' },
          keyAttributes: { type: 'array', items: { type: 'string' }, description: '主要属性（5-12个，含枚举/链接关系）' },
          links: { type: 'array', items: { type: 'string' }, description: '与其他实体的关联关系' },
          actions: { type: 'array', items: { type: 'string' }, description: '该实体上的动作/审批' },
        },
      },
    },
    snapshotFacts: {
      type: 'array',
      description: '所有 kind=SEMANTIC_MODEL isPersistent=false 的快照/事实 class（约17个）',
      items: {
        type: 'object',
        required: ['name', 'title', 'dataSet'],
        properties: {
          name: { type: 'string' },
          title: { type: 'string' },
          dataSet: { type: 'string', description: '来源数据集/实体类全名，如 cn.byteawake.prh.Resident' },
          dimensions: { type: 'array', items: { type: 'string' }, description: '维度字段' },
          measures: { type: 'array', items: { type: 'string' }, description: '度量/统计字段' },
        },
      },
    },
    enums: { type: 'array', items: { type: 'string' }, description: '所有枚举 name(title)，含取值要点' },
    businessRules: { type: 'array', items: { type: 'string' }, description: '主要 action/businessRule/校验函数要点' },
    notable: { type: 'array', items: { type: 'string' }, description: '值得注意的设计点/异常（如标题为空、命名不一致、特殊kind等）' },
  },
}

const prhOntology = await agent(`仔细完整阅读 ${ROOT}/model/ontology/byteawake-prh.cn.byteawake.prh.xml（3050行，必须分段读完整个文件，不要只读开头）。这是公租房系统的核心本体定义。

任务：
1. 提取全部 22 个持久化实体 class（如 Resident/Household/Residence/Employment/PersonalIncome/EligibilityApplication/HousingAllocation/RentalSubsidy/Attendance/Leave/AttendanceMakeup/MigrantWork/ResidenceChange/EmploymentChange/EligibilityTermination/HouseholdMember/HouseholdMemberChange/AttendanceSolution/AttendanceRule/LeaveType 等），记录 name、title、dataSet(物理表名)、主要属性、links 关联、actions。
2. 提取全部 kind="SEMANTIC_MODEL" isPersistent="false" 的快照/事实 class（约17个，名字以 SnapshotFact 或 Fact 结尾），记录 name、title、dataSet(指向来源实体类全名)、维度、度量。这是重点。
3. 提取全部 enum 和 struct。
4. 提取关键 action / businessRule / 校验函数 / datasource。
5. notable 记录任何异常：比如 HouseholdSnapshotFact 的 title 是空的、命名不一致、特殊配置等。

务必覆盖全部内容，用中文。`, { schema: ONTOLOGY_SCHEMA, phase: '读本体XML', label: 'prh.xml核心本体' })

const platformOntology = await agent(`阅读 ${ROOT}/model/ontology/ 下的平台层 6 个 XML：byteawake-ap-oms（528行,本体元模型）、byteawake-ap-oql（135行,查询）、byteawake-ap-approval（66行,审批）、byteawake-ap-arche（4852行,租户/用户/企业,只读结构概览即可不必逐行）、byteawake-ap-basedoc（169行,行政区划基础档案）、byteawake-ap-resource（483行,日历/考勤/请假资源）。

提炼每个命名空间提供的核心能力，以及 prh 本体如何 import 复用它们（审批 i_approval_flow、用户 User、行政区划 AdministrativeRegion、考勤日历 Calendar 等）。用中文。entityClasses 填各平台模块的关键对象，summary 给整体平台分层说明。`, { schema: ONTOLOGY_SCHEMA, phase: '读本体XML', label: '平台层XML' })

// ---------- Phase 3: prototype + frontend (parallel) ----------
phase('读原型与前端')

const PROTO_SCHEMA = {
  type: 'object',
  required: ['summary', 'screens', 'concepts'],
  properties: {
    summary: { type: 'string', description: '原型整体是什么、面向谁、解决什么（中文）' },
    screens: { type: 'array', items: { type: 'string' }, description: '原型包含的界面/面板/区域' },
    concepts: { type: 'array', items: { type: 'string' }, description: '原型体现的本体元数据/工作台核心概念（如 class、dataSet、fact、action 的可视化编辑）' },
    interactions: { type: 'array', items: { type: 'string' }, description: '关键交互/工作流' },
    relationToProject: { type: 'string', description: '这个原型与当前前端代码/本体模型的关系（中文）' },
  },
}

const FRONTEND_SCHEMA = {
  type: 'object',
  required: ['summary', 'pageGroups'],
  properties: {
    summary: { type: 'string', description: '前端整体结构（中文）' },
    pageGroups: {
      type: 'array',
      description: '按路由分组的页面',
      items: {
        type: 'object',
        required: ['group', 'pages'],
        properties: {
          group: { type: 'string', description: '分组名，如 Monitor/Report/Eligibility/Profile/Approval/System' },
          purpose: { type: 'string' },
          pages: { type: 'array', items: { type: 'string' }, description: '该组页面文件名及作用' },
          backingEntity: { type: 'array', items: { type: 'string' }, description: '该组页面对应的本体实体/快照事实' },
        },
      },
    },
    reportFactMapping: { type: 'array', items: { type: 'string' }, description: 'Report 页面与 fact-metric-registry/configs 中快照事实的对应关系（每条: 页面->fact->dataSet）' },
    serviceLayer: { type: 'array', items: { type: 'string' }, description: '服务层 domains 与 mock 的职责要点' },
    notable: { type: 'array', items: { type: 'string' }, description: '设计亮点/疑似缺口/与本体不一致处' },
  },
}

const [proto, frontend] = await parallel([
  () => agent(`阅读 ${ROOT}/2026-05-06_005_本体元数据系统工作台原型_改进版.html（3198行 HTML 原型，分段读完）。这是"本体元数据系统工作台"的设计原型。提炼它呈现的界面结构、它体现的本体平台核心概念（如何可视化管理 ontology/class/dataSet/fact/action）、关键交互工作流，以及它与当前这个公租房前端项目和 prh.xml 本体的关系。用中文。`, { schema: PROTO_SCHEMA, phase: '读原型与前端', label: 'HTML原型工作台' }),
  () => agent(`分析前端代码结构。先读 ${ROOT}/config/routes.ts（498行,完整路由）了解菜单与页面映射。再浏览 ${ROOT}/src/pages/ 下各分组页面（Monitor 监测变更类、Report 报表类、Eligibility 资格类、Profile 家庭档案、Residents 居民、Approval 审批、AttendanceConfig 考勤配置、System 系统管理、Fence 围栏、Filter 筛选器、Dashboard）。读 ${ROOT}/src/pages/Report/configs.tsx（608行）和 ${ROOT}/src/services/_mock-lib/fact-metric-registry.ts（312行）了解报表页如何映射到快照事实及其维度/度量。读 ${ROOT}/src/services/domains/index.ts 和几个关键 domain（facts.ts, change.ts, eligibility.ts, approval.ts）了解服务层。

重点产出 reportFactMapping：每个 Report 页面对应哪个 SnapshotFact/Fact 及其来源 dataSet。pageGroups 覆盖全部页面分组并标注每组背后的本体实体。用中文。`, { schema: FRONTEND_SCHEMA, phase: '读原型与前端', label: '前端页面与服务' }),
])

// ---------- Phase 4: git evolution ----------
phase('读git改动')

const GIT_SCHEMA = {
  type: 'object',
  required: ['commits', 'overallDirection'],
  properties: {
    overallDirection: { type: 'string', description: '最近改动的总体演进方向（中文）' },
    commits: {
      type: 'array',
      items: {
        type: 'object',
        required: ['hash', 'intent'],
        properties: {
          hash: { type: 'string' },
          intent: { type: 'string', description: '该提交的设计意图（不是逐行罗列，而是为什么这么改）' },
          impact: { type: 'string', description: '对本体/页面/服务的影响' },
        },
      },
    },
    themes: { type: 'array', items: { type: 'string' }, description: '贯穿多次提交的主题（如审批流、预警视图化、RBAC、字典中心）' },
  },
}

const git = await agent(`在 ${ROOT} 仓库，用 git 分析最近 6 条提交（2d9b493, dba45d6, eba7445, 50143ab, 0e97a80, ec87d71）。对每条用 \`git show --stat <hash>\` 和必要时 \`git show <hash> -- <关键文件>\` 查看 diff。提炼每条提交的设计意图（为什么改，不是逐行罗列）和对本体模型/页面/服务层的影响。特别关注：审批面板与多级审批流、预警从独立 Alert 实体改为基于 AttendanceFact 的只读视图、RBAC/系统配置/通知服务、Dashboard 报表卡片与字典中心。给出贯穿性主题。用中文。`, { schema: GIT_SCHEMA, phase: '读git改动', label: 'git演进分析' })

// ---------- Phase 5: synthesis — the key mapping ----------
phase('综合映射')

const bundle = {
  docs: docs.filter(Boolean),
  prhOntology,
  platformOntology,
  proto,
  frontend,
  git,
}

const synthesis = await agent(`你是本体与前端架构分析师。基于下面汇总的结构化分析结果（JSON），产出一份**完整的中文 Markdown 分析报告**，作为你的返回文本（不要再调用工具，直接输出 Markdown 正文）。

汇总数据：
\`\`\`json
${JSON.stringify(bundle, null, 2)}
\`\`\`

报告必须包含以下章节：

## 1. 项目概览
系统是什么、技术栈、本体平台(字节觉醒OMS)与前端的关系、整体分层。

## 2. 文档体系解读
分别概述：需求设计文档、本体与需求对齐分析报告、本体改动集（交接本体团队）、平台模型/Action指南、README、HTML原型工作台 各自讲了什么、相互关系。

## 3. 本体模型结构
- 22 个持久化实体表（按业务域分组：居民档案/资格配租/考勤请假/监测变更/配置），列 name、title、dataSet 物理表。
- 24 个枚举与 struct 概览。
- 平台层复用（审批/用户/行政区划/考勤日历）。

## 4. 【核心】快照事实 → 设计表 → 页面 三方映射表
这是用户最关心的部分。为 prh.xml 中**每一个** SEMANTIC_MODEL 快照/事实 class 建一行 Markdown 表格，列：
| 快照/事实 (name) | 中文标题 | dataSet 来源/设计表 | 对应前端页面 | Report配置/metric | 说明 |
把 prhOntology.snapshotFacts 与 frontend.reportFactMapping / pageGroups 做 join。若某个快照事实没有对应页面，或某页面找不到对应快照，明确标注"缺口"。

## 5. 页面与本体实体对照
按页面分组列出每组背后的实体/动作，标注哪些是直接 CRUD 实体页、哪些是快照事实只读报表页、哪些是审批/配置页。

## 6. 近期演进方向（git）
总结最近 6 次提交的主线（审批流、预警视图化、RBAC、Dashboard 等）。

## 7. 缺口与风险清单
综合"对齐分析报告""本体改动集"的待办，以及你在 join 过程中发现的不一致（如 HouseholdSnapshotFact 标题为空、快照事实与页面/configs 不匹配、命名不一致、文档与实现偏差等），列成可执行清单。

## 8. 建议的下一步
基于以上，给出 5-8 条优先级排序的建议。

要求：表格完整、不遗漏任何快照事实；结论基于数据，不臆测；明确区分"已确认"与"需进一步核对"。`, { phase: '综合映射', label: '综合分析报告' })

log('分析完成，生成综合报告')
return synthesis

