/**
 * services/auth.js — 登录认证
 *
 * arche.User 域:
 *   - sendOTP        发送验证码 (手机号/邮箱)
 *   - authenticate   账号密码 / 手机验证码登录
 *   - signup         注册
 *   - changeProfile  修改资料
 *
 * 微信小程序登录走 WECHAT_LOGIN_ACTION,后端确认动作名后改这一处即可。
 */

import { OBJECT_TYPES, WECHAT_LOGIN_ACTION } from '../utils/api'
import { callPayloadAction, unwrapResponseData } from '../utils/request'
import { setToken, setUserInfo } from './storage'

function pickToken(payload) {
	if (!payload || typeof payload !== 'object') {
		return ''
	}
	return payload.token || payload.accessToken || payload.sessionId || ''
}

function persistLoginPayload(payload, profilePatch = {}) {
	const data = payload && typeof payload === 'object' ? payload : {}
	const userInfo = {
		...data,
		...profilePatch,
		name: profilePatch.name || data.name || data.nickName || data.nickname || data.realName || data.fullName || '居民',
		avatarUrl: profilePatch.avatarUrl || data.avatarUrl || data.avatar || '',
		loginTime: Date.now()
	}

	const token = pickToken(userInfo)
	setToken(token)
	setUserInfo(userInfo)
	return userInfo
}

export function sendSmsOTP(phone) {
	return callPayloadAction('sendOTP', OBJECT_TYPES.user, { phone })
}

/**
 * 手机号 + 验证码登录
 *
 * 短信验证码登录字段名以后端实现为准,目前默认 phone + code。
 */
export async function loginByPhone({ phone, code }) {
	const response = await callPayloadAction('authenticate', OBJECT_TYPES.user, {
		phone,
		code
	})
	const payload = unwrapResponseData(response)
	const data = Array.isArray(payload) ? payload[0] : payload
	return persistLoginPayload(data, { phone, loginType: 'sms' })
}

export async function loginByPassword({ account, password }) {
	const response = await callPayloadAction('authenticate', OBJECT_TYPES.user, {
		account,
		password
	})
	const payload = unwrapResponseData(response)
	const data = Array.isArray(payload) ? payload[0] : payload
	return persistLoginPayload(data, { account, loginType: 'password' })
}

/**
 * 微信小程序一键登录: uni.login 拿 code → 调本体动作换 token/userInfo
 */
export async function loginByWechat(profile = {}) {
	const loginRes = await new Promise((resolve, reject) => {
		uni.login({
			provider: 'weixin',
			success: (res) => {
				if (!res.code) {
					reject(new Error('微信登录失败'))
					return
				}
				resolve(res)
			},
			fail: (err) => reject(new Error((err && err.errMsg) || '拉起微信登录失败'))
		})
	})

	const response = await callPayloadAction(WECHAT_LOGIN_ACTION, OBJECT_TYPES.user, {
		code: loginRes.code,
		userInfo: profile,
		nickName: profile.nickName || '',
		avatarUrl: profile.avatarUrl || '',
		gender: profile.gender || 0,
		province: profile.province || '',
		city: profile.city || '',
		country: profile.country || '',
		language: profile.language || ''
	})

	const payload = unwrapResponseData(response)
	const hasNestedUserInfo = payload && typeof payload === 'object' && payload.userInfo && typeof payload.userInfo === 'object'
	const data = hasNestedUserInfo
		? { ...payload, ...payload.userInfo }
		: (Array.isArray(payload) ? payload[0] : payload)

	if (!data || typeof data !== 'object') {
		throw new Error('登录接口返回数据异常')
	}

	return persistLoginPayload(data, {
		nickName: profile.nickName,
		avatarUrl: profile.avatarUrl,
		gender: profile.gender,
		loginType: 'wechat',
		wxCode: loginRes.code
	})
}

