} from '../utils/request'

function buildAddress({ regionId, detail, longitude, latitude }) {
	const address = {
		region: regionId || '',
		detail: detail || ''
	}
	if (longitude !== undefined && latitude !== undefined) {
		address.geoPoint = { longitude, latitude }
	}
	return address
}

export function submitRecord(input) {
	const {
		recordType,
		residentId,
		address,
		workplace,
		startDate,
		endDate,
		returnDate,
		regionId,
		longitude,
		latitude
	} = input

	const prhAddress = buildAddress({
		regionId,
		detail: address,
		longitude,
		latitude
	})

	if (recordType === 'work') {
		return callPayloadAction('add', OBJECT_TYPES.migrantWork, {
			resident: residentId,
			employer: workplace || '',
			workAddress: prhAddress,
			startDate,
