/**
 * services/message.js — 消息中心
 *
 * 后端 byteawake 手册没有显式的 Notification 实体,目前消息有两类:
 *   - approval: 通过 IApprovalFlow 字段查的审批结果(真实数据)
 *   - reminder: 基于本地状态推导的提醒(未打卡 / 请假到期 / 备案到期等)
 *   - system:   系统通知(后端给出消息本体后再接,目前为版本/服务公告 stub)
 */

import { OBJECT_TYPES } from '../utils/api'
import { callList } from '../utils/request'
import { isCheckedInToday, listResidentAttendance } from './attendance'
import { listResidentLeaves } from './leave'
import { listResidentRecords } from './record'

function buildApprovalMessage(item, sourceLabel) {
	const verifyState = item.verifyState
	let title = `${sourceLabel}审批通知`
	let desc = ''
	if (verifyState === 20 || verifyState === 'APPROVED') {
		title = `${sourceLabel}已通过`
		desc = '您的申请已通过审批'
	} else if (verifyState === 30 || verifyState === 'REJECTED') {
		title = `${sourceLabel}已驳回`
		desc = '您的申请被驳回,请查看详情'
	} else if (verifyState === 40 || verifyState === 'RETURNED') {
		title = `${sourceLabel}已退回`
		desc = '您的申请被退回,请补充资料'
	} else {
		title = `${sourceLabel}审批中`
		desc = '您的申请提交成功,等待审批'
	}

	return {
		id: item.id,
		category: 'approval',
		title,
		desc,
		time: item.modifyAt || item.createAt || '',
		variant: verifyState === 30 ? 'alert' : (verifyState === 20 ? 'success' : 'warning')
	}
}

export async function fetchApprovalMessages({ residentId, householdId } = {}) {
	const tasks = []

	if (residentId) {
		tasks.push(
			callList(OBJECT_TYPES.residenceChange, {
				selection: 'id,verifyState,modifyAt,createAt',
				filter: {
					operator: 'AND',
					conditions: [{ field: 'resident', operator: 'EQ', value1: residentId }]
				},
				page: { pageNo: 1, pageSize: 20 }
			})
				.then((res) => res.data.map((item) => buildApprovalMessage(item, '居住备案')))
				.catch(() => [])
		)
	}

	if (householdId) {
		tasks.push(
			callList(OBJECT_TYPES.eligibilityApplication, {
				selection: 'id,verifyState,modifyAt,createAt',
				filter: {
					operator: 'AND',
					conditions: [{ field: 'household', operator: 'EQ', value1: householdId }]
				},
				page: { pageNo: 1, pageSize: 20 }
			})
				.then((res) => res.data.map((item) => buildApprovalMessage(item, '保障资质')))
				.catch(() => [])
		)
	}

	const results = await Promise.all(tasks)
	return [].concat.apply([], results)
}

function daysBetween(future) {
	if (!future) return null
	const t = new Date(future).getTime()
	if (!Number.isFinite(t)) return null
	const ms = t - Date.now()
	return Math.ceil(ms / 86400000)
}

function nowISO() {
	return new Date().toISOString()
}

/**
 * 提醒类消息(本地推导,无后端依赖)
 *
 * 规则:
 *   - 未打卡(已是 10:00 后)→ '今日打卡提醒'
 *   - 进行中的请假今天到期 → '请假即将结束'
 *   - 生效中的备案 5 天内到期 → '备案即将到期'
 *   - 最近 7 天内有缺勤打卡(status=MISSED)→ '缺勤打卡提醒'
 */
export async function fetchReminderMessages({ residentId } = {}) {
	if (!residentId) {
		return []
	}

	const reminders = []

	// 1. 今日是否未打卡(且当前时间 ≥ 10:00)
	const checkedTask = isCheckedInToday(residentId).catch(() => true)
	const now = new Date()
	const past10am = now.getHours() >= 10
	const checked = await checkedTask
	if (!checked && past10am) {
		reminders.push({
			id: `reminder-checkin-${now.toDateString()}`,
			category: 'reminder',
			title: '今日打卡提醒',
			desc: '请尽快完成今日居住打卡,避免影响居住状态评估',
			time: nowISO(),
			variant: 'warning'
		})
	}

	// 2. 进行中的请假
	const leaveRes = await listResidentLeaves({
		residentId,
		status: 'COMPLETED',
		page: { pageNo: 1, pageSize: 5 }
	}).catch(() => ({ data: [] }))
	leaveRes.data.forEach((leave) => {
		const days = daysBetween(leave.endDate)
		if (days !== null && days >= 0 && days <= 1) {
			reminders.push({
				id: `reminder-leave-${leave.id}`,
				category: 'reminder',
				title: '请假即将结束',
				desc: `您的请假将于 ${leave.endDate} 结束,届时请按时打卡`,
				time: nowISO(),
				variant: 'warning'
			})
		}
	})

	// 3. 生效中的备案 5 天内到期
	const recordRes = await listResidentRecords({
		residentId,
		page: { pageNo: 1, pageSize: 5 }
	}).catch(() => ({ data: [] }))
	recordRes.data
		.filter((r) => r.status === 'RECORD_ACTIVE')
		.forEach((record) => {
			const days = daysBetween(record.endDate)
			if (days !== null && days >= 0 && days <= 5) {
				reminders.push({
					id: `reminder-record-${record.id}`,
					category: 'reminder',
					title: '备案即将到期',
					desc: `备案将于 ${record.endDate} 到期${days > 0 ? `(还有 ${days} 天)` : '(今天)'},如需延期请提前申请`,
					time: nowISO(),
					variant: 'warning'
				})
			}
		})

	// 4. 最近 7 天缺勤
	const sevenDaysAgo = new Date(Date.now() - 7 * 86400000).toISOString()
	const todayEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59).toISOString()
	const attendanceRes = await listResidentAttendance({
		residentId,
		startDate: sevenDaysAgo,
		endDate: todayEnd,
		page: { pageNo: 1, pageSize: 20 }
	}).catch(() => ({ data: [] }))
	const missedCount = attendanceRes.data.filter((a) => a.status === 'MISSED').length
	if (missedCount > 0) {
		reminders.push({
			id: `reminder-missed-${now.toDateString()}`,
			category: 'reminder',
			title: '缺勤打卡提醒',
			desc: `近 7 天检测到 ${missedCount} 次缺勤打卡,请尽快补卡或提交说明`,
			time: nowISO(),
			variant: 'alert'
		})
	}

	return reminders
}

/**
 * 系统通知(版本/服务公告类)
 *
 * 没有后端本体之前,先返回固定的版本说明 stub,避免空 tab。
 * 后端 Notification 本体上线后,这里改成 callList 即可。
 */
export async function fetchSystemMessages() {
	return [
		{
			id: 'sys-welcome',
			category: 'system',
			title: '欢迎使用居住监测小程序',
			desc: '请按时完成每日居住打卡。如有疑问请联系所在街道管理员。',
			time: '',
			variant: 'info'
		}
	]
}

export async function fetchMessages({ tab = 'all', residentId, householdId } = {}) {
	if (tab === 'approval') {
		return fetchApprovalMessages({ residentId, householdId })
	}
	if (tab === 'system') {
		return fetchSystemMessages()
	}
	if (tab === 'reminder') {
		return fetchReminderMessages({ residentId })
	}

	const [approval, reminder, system] = await Promise.all([
		fetchApprovalMessages({ residentId, householdId }),
		fetchReminderMessages({ residentId }),
		fetchSystemMessages()
	])

	// 优先级:reminder > approval > system
	return [].concat(reminder, approval, system)
}

