/**
 * 本体平台统一接入配置
 *
 * 后端遵循 byteawake OMS 本体规范，所有业务都走:
 *   POST {API_BASE_URL}{ONTOLOGY_ACTION_PREFIX}/{actionName}
 *   body: { objectType, payload } 或 { objectType, id }
 *
 * 联调时一般只需要修改 API_BASE_URL 一处即可。
 * 文件上传(附件服务)的地址单独配置在 UPLOAD_URL。
 */

// 后端服务根地址，例如 'https://api.example.com'
export const API_BASE_URL = ''

// 本体动作统一前缀，按手册默认 '/api/v1/ontology'
export const ONTOLOGY_ACTION_PREFIX = '/api/v1/ontology'

// 附件直传地址(uni.uploadFile 用)。返回需含 url、name、mimeType
export const UPLOAD_URL = ''

/**
 * 业务命名空间常量，便于在各 service 模块中引用，避免散落的字符串拼写错误
 */
export const OBJECT_TYPES = {
	// arche
	user: 'cn.byteawake.ap.arche.User',
	// basedoc
