/**
 * services/storage.js — 本地存储与登录态共用工具
 */

const TOKEN_KEY = 'token'
const USER_INFO_KEY = 'userInfo'
const RESIDENT_KEY = 'residentInfo'

function readJSON(key) {
	const value = uni.getStorageSync(key)
	if (!value) {
		return null
	}

	if (typeof value === 'string') {
		try {
			return JSON.parse(value)
		} catch (error) {
			return value
		}
	}

	return value
}

export function getToken() {
	const token = uni.getStorageSync(TOKEN_KEY)
	if (token) {
		return token
	}

	const userInfo = readJSON(USER_INFO_KEY)
	if (!userInfo || typeof userInfo !== 'object') {
		return ''
	}

	return userInfo.token || userInfo.accessToken || ''
}

export function setToken(token) {
	if (token) {
		uni.setStorageSync(TOKEN_KEY, token)
	} else {
		uni.removeStorageSync(TOKEN_KEY)
	}
}

export function getUserInfo() {
	return readJSON(USER_INFO_KEY) || null
}

export function setUserInfo(userInfo) {
	if (!userInfo) {
		uni.removeStorageSync(USER_INFO_KEY)
		return
	}
	uni.setStorageSync(USER_INFO_KEY, userInfo)
}

export function getResidentInfo() {
	return readJSON(RESIDENT_KEY) || null
}

export function setResidentInfo(resident) {
	if (!resident) {
		uni.removeStorageSync(RESIDENT_KEY)
		return
	}
	uni.setStorageSync(RESIDENT_KEY, resident)
}

export function clearLoginState() {
	uni.removeStorageSync(TOKEN_KEY)
	uni.removeStorageSync(USER_INFO_KEY)
	uni.removeStorageSync(RESIDENT_KEY)
}

