<script>
import { getUserInfo, getResidentInfo, setResidentInfo, setUserInfo } from '../../services/storage'
import { fetchResidentDetail, findResidentBy, modifyResident, uploadAvatar } from '../../services/resident'
import { changeProfile } from '../../services/auth'
import { fetchMessages } from '../../services/message'
import { listResidentLeaves } from '../../services/leave'
import { listResidentRecords } from '../../services/record'
import { isCheckedInToday } from '../../services/attendance'

const VERIFIED_STATUSES = ['VERIFIED', 'ACTIVATED']

export default {
	data() {
		return {
			userInfo: {
				name: '',
				realName: '',
				avatarUrl: '',
				phone: '',
				loginType: '',
				tenantId: ''
			},
			resident: null,
			activeLeave: null,
			activeRecord: null,
			messages: [],
			todayChecked: false
		}
	},
	onLoad() {
		this.loadUserInfo()
		this.loadResident()
	},
	onShow() {
		this.loadUserInfo()
		this.loadResident()
	},
	computed: {
		displayName() {
			if (this.resident && this.resident.fullName) {
				return this.resident.fullName
			}
			return this.userInfo.realName || this.userInfo.name || '居民'
		},
		accountLabel() {
			return this.userInfo.phone || (this.resident && this.resident.phone) ? '手机号：' : '账 号：'
		},
		accountValue() {
			const phone = this.userInfo.phone || (this.resident && this.resident.phone)
			if (phone) {
				return phone
			}
			const account = this.userInfo.account || this.userInfo.userId
			if (account) {
				return account
			}
			return '未绑定账号'
		},
		avatarText() {
			const name = this.displayName.trim()
			return name ? name.slice(0, 1) : '我'
		},
		isVerified() {
			return this.resident ? VERIFIED_STATUSES.indexOf(this.resident.status) !== -1 : false
		},
		hasActiveRecord() {
			return !!this.activeRecord
		},
		recordLocation() {
			if (!this.activeRecord) {
				return ''
			}
			const detail = (this.activeRecord.address && this.activeRecord.address.detail) || ''
			return detail || '已备案地点'
		},
		recordTimeLabel() {
			if (!this.activeRecord) {
				return ''
			}
			return `${this.activeRecord.residenceType || '备案'} · 有效期至 ${this.activeRecord.endDate || '—'}`
		}
	},
	methods: {
		loadUserInfo() {
			const stored = getUserInfo()
			if (!stored) {
				return
			}
			this.userInfo = {
				...this.userInfo,
				...stored
			}
		},
		async loadResident() {
			const cached = getResidentInfo()
			if (cached) {
				this.resident = cached
			}

			const user = getUserInfo()
			if (!user) {
				return
			}

			try {
				let resident = null
				if (user.residentId) {
					resident = await fetchResidentDetail(user.residentId)
				} else if (this.resident && this.resident.id) {
					resident = await fetchResidentDetail(this.resident.id)
				} else {
					resident = await findResidentBy({
						phone: user.phone,
						idCardNo: user.idCardNumber || user.idCardNo,
						userId: user.userId || user.id
					})
				}

				if (resident) {
					this.resident = resident
					setResidentInfo(resident)
					this.loadActiveLeave(resident.id)
					this.loadActiveRecord(resident.id)
					this.loadRecentMessages(resident.id, resident.householdId)
					this.checkTodayAttendance(resident.id)
				}
			} catch (error) {
				console.warn('加载居民信息失败', error)
			}
		},
		async checkTodayAttendance(residentId) {
			try {
				this.todayChecked = await isCheckedInToday(residentId)
			} catch (error) {
				this.todayChecked = false
			}
		},
		async loadActiveLeave(residentId) {
			try {
				const result = await listResidentLeaves({
					residentId,
					status: 'COMPLETED',
					page: { pageNo: 1, pageSize: 1 }
				})
				this.activeLeave = result.data[0] || null
			} catch (error) {
				this.activeLeave = null
			}
		},
		async loadActiveRecord(residentId) {
			try {
				const result = await listResidentRecords({
					residentId,
					page: { pageNo: 1, pageSize: 5 }
				})
				const active = result.data.find((item) => item.status === 'RECORD_ACTIVE')
				this.activeRecord = active || result.data[0] || null
			} catch (error) {
				this.activeRecord = null
			}
		},
		async loadRecentMessages(residentId, householdId) {
			try {
				const list = await fetchMessages({ tab: 'all', residentId, householdId })
				this.messages = list.slice(0, 2)
			} catch (error) {
				this.messages = []
			}
		},
		goCheckin() {
			uni.navigateTo({ url: '/pages/checkin/checkin' })
		},
		goLeave() {
			uni.navigateTo({ url: '/pages/leave/leave' })
		},
		viewAllMessages() {
			uni.navigateTo({ url: '/pages/message/message' })
		},
		renewRecord() {
			uni.navigateTo({ url: '/pages/record/record' })
		},
		cancelRecord() {
			uni.showModal({
				title: '撤销备案',
				content: '撤销后该备案将立即失效,请确认。',
				success: (res) => {
					if (res.confirm) {
						uni.showToast({ title: '撤销功能待后端动作上线', icon: 'none' })
					}
				}
			})
		},
		changeAvatar() {
			uni.chooseImage({
				count: 1,
				sizeType: ['compressed'],
				sourceType: ['album', 'camera'],
				success: async (res) => {
					const filePath = res.tempFilePaths && res.tempFilePaths[0]
					if (!filePath) {
						return
					}

					uni.showLoading({ title: '上传中...' })
					try {
						const attachment = await uploadAvatar(filePath)
						const url = attachment.url
						if (!url) {
							throw new Error('上传未返回 url')
						}

						// 同步到 arche.User.avatar 和 prh.Resident.facePhoto(可能没此权限,失败不阻塞)
						const tasks = []
						tasks.push(
							changeProfile({ avatar: url }).catch((err) => {
								console.warn('更新 User.avatar 失败', err)
							})
						)
						if (this.resident && this.resident.id) {
							tasks.push(
								modifyResident({ id: this.resident.id, facePhoto: url }).catch((err) => {
									console.warn('更新 Resident.facePhoto 失败', err)
								})
							)
						}
						await Promise.all(tasks)

						this.userInfo = { ...this.userInfo, avatarUrl: url }
						setUserInfo(this.userInfo)
						if (this.resident) {
							const next = { ...this.resident, facePhoto: url }
							this.resident = next
							setResidentInfo(next)
						}

						uni.hideLoading()
						uni.showToast({ title: '头像已更新', icon: 'success' })
					} catch (error) {
						uni.hideLoading()
						uni.showToast({ title: error.message || '更新头像失败', icon: 'none' })
					}
				}
			})
		}
	}
}
</script>

