/**
 * services/region.js — 行政区划 (cn.byteawake.ap.basedoc.AdministrativeRegion)
 */

import { OBJECT_TYPES } from '../utils/api'
import { callAction, callList } from '../utils/request'

export async function queryRegionTree({ rootId, maxDepth = 3 } = {}) {
	const response = await callAction('querytree', {
		objectType: OBJECT_TYPES.region,
		payload: {
			selection: 'id,code,name,regionType,parent,level',
			filter: {
				operator: 'AND',
				conditions: [
					{ field: 'enable', operator: 'EQ', value1: 'true' },
					{ field: 'dr', operator: 'EQ', value1: 'false' }
				]
			},
			treeOptions: {
				rootId: rootId || null,
				scope: 'SUBTREE',
				recursive: true,
				maxDepth
			}
		}
	})

	return (response && response.data) || []
}

export function referRegion(keyword) {
	return callList(OBJECT_TYPES.region, {
		selection: 'id,code,name,regionType,path',
		filter: {
			operator: 'AND',
			conditions: keyword
				? [{ field: 'name', operator: 'LIKE', value1: keyword }]
				: []
		},
		page: { pageNo: 1, pageSize: 20 }
	}, 'refer')
}

