import { API_BASE_URL, ONTOLOGY_ACTION_PREFIX, UPLOAD_URL } from './api'

const SUCCESS_CODES = [0, 1, 200, '0', '1', '200', 'SUCCESS', 'success', 'OK', 'ok']

function isAbsoluteUrl(url) {
	return /^https?:\/\//.test(url)
}

function joinUrl(baseURL, url) {
	if (!url) {
		return ''
	}

	if (isAbsoluteUrl(url) || !baseURL) {
		return url
	}

	const normalizedBase = baseURL.endsWith('/') ? baseURL.slice(0, -1) : baseURL
	const normalizedPath = url.startsWith('/') ? url : `/${url}`
	return `${normalizedBase}${normalizedPath}`
}

function getStorageObject(key) {
	const value = uni.getStorageSync(key)
	if (!value) {
		return null
	}

	if (typeof value === 'string') {
		try {
			return JSON.parse(value)
		} catch (error) {
			return value
		}
	}

	return value
}

function getToken() {
	const token = uni.getStorageSync('token')
	if (token) {
		return token
	}

	const userInfo = getStorageObject('userInfo')
	if (!userInfo || typeof userInfo !== 'object') {
		return ''
	}

	return userInfo.token || userInfo.accessToken || ''
}

function buildHeaders(customHeaders = {}, options = {}) {
	const { includeJsonContentType = true } = options
	const headers = {
		...(includeJsonContentType ? { 'Content-Type': 'application/json' } : {}),
		...customHeaders
	}

	const token = getToken()
	if (token && !headers.Authorization && !headers.authorization) {
		headers.Authorization = `Bearer ${token}`
	}

	return headers
}

function formatFieldErrors(fieldErrors) {
	if (!Array.isArray(fieldErrors) || !fieldErrors.length) {
		return ''
	}

	return fieldErrors
		.map((err) => {
			if (!err || typeof err !== 'object') {
				return ''
			}

			const path = err.path || err.field || ''
			const message = err.message || err.msg || ''
			return path ? `${path}: ${message}` : message
		})
		.filter(Boolean)
		.join('；')
}

function getErrorMessage(data, fallback = '请求失败') {
	if (!data || typeof data !== 'object') {
		return fallback
	}

	const fieldErrorMessage = formatFieldErrors(data.fieldErrors)
	if (fieldErrorMessage) {
		return fieldErrorMessage
	}

	return data.message || data.msg || data.errMsg || data.errorMessage || fallback
}

function isBusinessSuccess(data) {
	if (!data || typeof data !== 'object' || Array.isArray(data)) {
		return true
	}

	if (data.success === true) {
		return true
	}

	if (data.success === false) {
		return false
	}

	if (data.code === undefined && data.status === undefined && data.errorCode === undefined) {
		return true
	}

	const code = data.code !== undefined
		? data.code
		: (data.status !== undefined ? data.status : data.errorCode)

	return SUCCESS_CODES.includes(code)
}

function parseResponseData(rawData) {
	if (typeof rawData !== 'string') {
		return rawData
	}

	try {
		return JSON.parse(rawData)
	} catch (error) {
		return rawData
	}
}

function buildBusinessError(data, fallback) {
	const message = getErrorMessage(data, fallback)
	const error = new Error(message)
	if (data && typeof data === 'object') {
		error.code = data.code
		error.fieldErrors = Array.isArray(data.fieldErrors) ? data.fieldErrors : []
		error.raw = data
	}
	return error
}

let redirectingToLogin = false
function redirectToLoginOnce() {
	if (redirectingToLogin) {
		return
	}
	redirectingToLogin = true

	try {
		uni.removeStorageSync('token')
	} catch (error) {
		// noop
	}

	uni.reLaunch({
		url: '/pages/login/login',
		complete: () => {
			redirectingToLogin = false
		}
	})
}

function validateResponse(statusCode, data, fallbackMessage) {
	if (statusCode === 401 || statusCode === 403) {
		redirectToLoginOnce()
		throw buildBusinessError(data, '登录已过期,请重新登录')
	}

	if (statusCode < 200 || statusCode >= 300) {
		throw buildBusinessError(data, `${fallbackMessage}(${statusCode})`)
	}

	if (!isBusinessSuccess(data)) {
		const code = data && (data.code || data.errorCode)
		if (code === 'UNAUTHORIZED' || code === 'TOKEN_EXPIRED' || code === 401) {
			redirectToLoginOnce()
		}
		throw buildBusinessError(data, '业务请求失败')
	}

	return data
}

export function unwrapResponseData(data) {
	if (!data || typeof data !== 'object' || !('data' in data)) {
		return data
	}

	return data.data
}

export function request(options = {}) {
	const {
		url,
		method = 'GET',
		data,
		header,
		timeout = 15000
	} = options

	return new Promise((resolve, reject) => {
		if (!url) {
			reject(new Error('未配置请求地址'))
			return
		}

		uni.request({
			url: joinUrl(API_BASE_URL, url),
			method,
			data,
			timeout,
			header: buildHeaders(header),
			success: (res) => {
				try {
					const responseData = validateResponse(res.statusCode || 0, res.data, '请求失败')
					resolve(responseData)
				} catch (error) {
					reject(error)
				}
			},
			fail: (error) => {
				reject(new Error((error && error.errMsg) || '网络请求失败'))
			}
		})
	})
}

export function uploadFile(options = {}) {
	const {
		url = UPLOAD_URL,
		filePath,
		name = 'file',
		formData = {},
		header,
		timeout = 30000
	} = options

	return new Promise((resolve, reject) => {
		if (!url) {
			reject(new Error('未配置上传地址'))
			return
		}

		if (!filePath) {
			reject(new Error('缺少上传文件'))
			return
		}

		uni.uploadFile({
			url: joinUrl(API_BASE_URL, url),
			filePath,
			name,
			formData,
			timeout,
			header: buildHeaders(header, { includeJsonContentType: false }),
			success: (res) => {
				try {
					const responseData = parseResponseData(res.data)
					const validatedData = validateResponse(res.statusCode || 0, responseData, '上传失败')
					resolve(validatedData)
				} catch (error) {
					reject(error)
				}
			},
			fail: (error) => {
				reject(new Error((error && error.errMsg) || '文件上传失败'))
			}
		})
	})
}

export function get(url, options = {}) {
	return request({
		...options,
		url,
		method: 'GET'
	})
}

export function post(url, data = {}, options = {}) {
	return request({
		...options,
		url,
		data,
		method: 'POST'
	})
}

/**
 * 调用本体动作
 *
 * @param {string} actionName  动作名,如 'add' / 'list' / 'submit' / 'verify'
 * @param {object} body        透传给 OMS 的请求体,不要再嵌套 objectType/payload
 * @param {object} [options]   透传给底层 request 的选项
 * @returns {Promise<object>}  完整 OntologyResult(带 success/code/data/page 等)
 */
export function callAction(actionName, body, options = {}) {
	if (!actionName) {
		return Promise.reject(new Error('未指定动作名'))
	}

	const url = `${ONTOLOGY_ACTION_PREFIX.replace(/\/$/, '')}/${actionName}`
	return request({
		...options,
		url,
		method: 'POST',
		data: body || {}
	})
}

/**
 * 写动作快捷调用,固定 { objectType, payload } 格式
 */
export function callPayloadAction(actionName, objectType, payload = {}, options = {}) {
	return callAction(actionName, { objectType, payload }, options)
}

/**
 * 单对象动作快捷调用,固定 { objectType, id } 格式
 * 适用 submit/unsubmit/activate/archive/enable/stop/delete/detail 等
 */
export function callIdAction(actionName, objectType, id, options = {}) {
	return callAction(actionName, { objectType, id }, options)
}

/**
 * 列表查询快捷调用
 *
 * @param {string} objectType  目标本体
 * @param {object} querySpec   { selection, filter, sortItems, page, ... }
 * @returns {Promise<{ data: any[], page: object, raw: object }>}
 */
export async function callList(objectType, querySpec = {}, actionName = 'list') {
	const response = await callAction(actionName, {
		objectType,
		payload: querySpec
	})

	return {
		data: Array.isArray(response && response.data) ? response.data : [],
		page: (response && response.page) || null,
		raw: response
	}
}

/**
 * 详情快捷调用
 */
export async function callDetail(objectType, id) {
	const response = await callIdAction('detail', objectType, id)
	const data = unwrapResponseData(response)
	if (Array.isArray(data)) {
		return data[0] || null
	}
	return data || null
}

export default request
