			redirectToLoginOnce()
		}
		throw buildBusinessError(data, '业务请求失败')
	}

	return data
}

export function unwrapResponseData(data) {
	if (!data || typeof data !== 'object' || !('data' in data)) {
		return data
	}

	return data.data
}

export function request(options = {}) {
	const {
		url,
		method = 'GET',
		data,
		header,
		timeout = 15000
	} = options

	return new Promise((resolve, reject) => {
		if (!url) {
			reject(new Error('未配置请求地址'))
			return
		}

		uni.request({
			url: joinUrl(API_BASE_URL, url),
			method,
			data,
			timeout,
			header: buildHeaders(header),
			success: (res) => {
				try {
					const responseData = validateResponse(res.statusCode || 0, res.data, '请求失败')
					resolve(responseData)
				} catch (error) {
					reject(error)
				}
			},
			fail: (error) => {
				reject(new Error((error && error.errMsg) || '网络请求失败'))
			}
		})
	})
}

export function uploadFile(options = {}) {
	const {
		url = UPLOAD_URL,
		filePath,
		name = 'file',
		formData = {},
		header,
		timeout = 30000
	} = options

	return new Promise((resolve, reject) => {
		if (!url) {
			reject(new Error('未配置上传地址'))
			return
		}

		if (!filePath) {
			reject(new Error('缺少上传文件'))
			return
		}

		uni.uploadFile({
			url: joinUrl(API_BASE_URL, url),
			filePath,
			name,
			formData,
			timeout,
			header: buildHeaders(header, { includeJsonContentType: false }),
			success: (res) => {
				try {
					const responseData = parseResponseData(res.data)
					const validatedData = validateResponse(res.statusCode || 0, responseData, '上传失败')
					resolve(validatedData)
				} catch (error) {
					reject(error)
				}
			},
			fail: (error) => {
				reject(new Error((error && error.errMsg) || '文件上传失败'))
			}
		})
	})
}

export function get(url, options = {}) {
	return request({
		...options,
		url,
		method: 'GET'
	})
}

export function post(url, data = {}, options = {}) {
	return request({
		...options,
		url,
		data,
		method: 'POST'
	})
}

/**
 * 调用本体动作
 *
 * @param {string} actionName  动作名,如 'add' / 'list' / 'submit' / 'verify'
 * @param {object} body        透传给 OMS 的请求体,不要再嵌套 objectType/payload
 * @param {object} [options]   透传给底层 request 的选项
 * @returns {Promise<object>}  完整 OntologyResult(带 success/code/data/page 等)
 */
export function callAction(actionName, body, options = {}) {
	if (!actionName) {
		return Promise.reject(new Error('未指定动作名'))
	}

	const url = `${ONTOLOGY_ACTION_PREFIX.replace(/\/$/, '')}/${actionName}`
	return request({
		...options,
		url,
		method: 'POST',
		data: body || {}
	})
}

/**
 * 写动作快捷调用,固定 { objectType, payload } 格式
 */
export function callPayloadAction(actionName, objectType, payload = {}, options = {}) {
	return callAction(actionName, { objectType, payload }, options)
}

/**
 * 单对象动作快捷调用,固定 { objectType, id } 格式
 * 适用 submit/unsubmit/activate/archive/enable/stop/delete/detail 等
 */
export function callIdAction(actionName, objectType, id, options = {}) {
	return callAction(actionName, { objectType, id }, options)
}

/**
 * 列表查询快捷调用
 *
 * @param {string} objectType  目标本体
 * @param {object} querySpec   { selection, filter, sortItems, page, ... }
 * @returns {Promise<{ data: any[], page: object, raw: object }>}
 */
export async function callList(objectType, querySpec = {}, actionName = 'list') {
	const response = await callAction(actionName, {
		objectType,
		payload: querySpec
	})

	return {
		data: Array.isArray(response && response.data) ? response.data : [],
		page: (response && response.page) || null,
		raw: response
	}
}

/**
 * 详情快捷调用
 */
export async function callDetail(objectType, id) {
	const response = await callIdAction('detail', objectType, id)
	const data = unwrapResponseData(response)
	if (Array.isArray(data)) {
		return data[0] || null
	}
	return data || null
}

export default request

