/**
 * services/household.js — 家庭档案 + 家庭成员
 *
 * 实体:
 *   - cn.byteawake.prh.Household        保障家庭
 *   - cn.byteawake.prh.HouseholdMember  家庭成员
 *
 * 居民端只读:查看自己所属家庭信息和成员列表。
 */

import { OBJECT_TYPES } from '../utils/api'
import { callList, callDetail } from '../utils/request'

/**
 * 获取家庭详情
 */
export function fetchHouseholdDetail(id) {
	return callDetail(OBJECT_TYPES.household, id)
}

/**
 * 查询居民所属家庭(通过 householdMember 反查)
 */
export async function findHouseholdByResident(residentId) {
	if (!residentId) return null

	const memberRes = await callList(OBJECT_TYPES.householdMember, {
		selection: 'id,household,resident,relationship,isIncluded',
		filter: {
			operator: 'AND',
			conditions: [{ field: 'resident', operator: 'EQ', value1: residentId }]
		},
		page: { pageNo: 1, pageSize: 1 }
	})

	const member = memberRes.data[0]
	if (!member || !member.household) return null

	const householdId = typeof member.household === 'object' ? member.household.id : member.household
	const household = await fetchHouseholdDetail(householdId)
	return household
}

/**
 * 查询家庭成员列表
 */
export function listHouseholdMembers(householdId) {
	if (!householdId) return Promise.resolve({ data: [], page: null })

	return callList(OBJECT_TYPES.householdMember, {
		selection: 'id,resident,relationship,isIncluded,joinAt',
		filter: {
			operator: 'AND',
			conditions: [{ field: 'household', operator: 'EQ', value1: householdId }]
		},
		sortItems: [{ path: 'joinAt', direction: 'ASC' }],
		page: { pageNo: 1, pageSize: 50 }
	})
}

