 * services/eligibility.js — 保障资格 / 配租 / 补贴(居民端只读)
 *
 * 实体:
 *   - cn.byteawake.prh.EligibilityApplication  保障资质申请
 *   - cn.byteawake.prh.HousingAllocation       实物配租
 *   - cn.byteawake.prh.RentalSubsidy           租赁补贴
 *   - cn.byteawake.prh.EligibilityTermination  资格终止
 *
 * 居民端:查看自己家庭的配租/补贴状态,不可编辑。
 */

import { OBJECT_TYPES } from '../utils/api'
import { callList, callDetail } from '../utils/request'

/**
 * 查询家庭的实物配租记录
 */
export function listHousingAllocations(householdId, { page = { pageNo: 1, pageSize: 10 } } = {}) {
	if (!householdId) return Promise.resolve({ data: [], page: null })

	return callList(OBJECT_TYPES.housingAllocation, {
		selection: 'id,projectName,buildingNo,unitNo,roomNo,area,monthlyRent,leaseStartDate,leaseEndDate,status',
		filter: {
			operator: 'AND',
			conditions: [{ field: 'household', operator: 'EQ', value1: householdId }]
		},
		sortItems: [{ path: 'leaseStartDate', direction: 'DESC' }],
		page
	})
}

/**
 * 查询家庭的租赁补贴记录
 */
export function listRentalSubsidies(householdId, { page = { pageNo: 1, pageSize: 10 } } = {}) {
	if (!householdId) return Promise.resolve({ data: [], page: null })

	return callList(OBJECT_TYPES.rentalSubsidy, {
		selection: 'id,monthlyAmount,startDate,endDate,status',
		filter: {
			operator: 'AND',
			conditions: [{ field: 'household', operator: 'EQ', value1: householdId }]
		},
		sortItems: [{ path: 'startDate', direction: 'DESC' }],
		page
	})
}

/**
 * 查询家庭的资格申请记录
 */
export function listEligibilityApplications(householdId, { page = { pageNo: 1, pageSize: 10 } } = {}) {
	if (!householdId) return Promise.resolve({ data: [], page: null })

	return callList(OBJECT_TYPES.eligibilityApplication, {
		selection: 'id,applicationType,guaranteeType,status,submittedAt,approvalResult,createAt',
		filter: {
			operator: 'AND',
			conditions: [{ field: 'household', operator: 'EQ', value1: householdId }]
		},
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

/**
 * 配租详情
 */
export function fetchAllocationDetail(id) {
	return callDetail(OBJECT_TYPES.housingAllocation, id)
}

/**
 * 补贴详情
 */
export function fetchSubsidyDetail(id) {
	return callDetail(OBJECT_TYPES.rentalSubsidy, id)
}

