/**
 * services/notification.js — 通知消息(真实 OT.Notification)
 *
 * 实体: cn.byteawake.prh.Notification
 *
 * 对接 PC 端 notificationService 的同名动作:
 *   - list       查询通知列表
 *   - markRead   标记单条已读
 *   - markAllRead 全部标记已读
 *   - process    预警类消息轻量处置
 *
 * 注意: 后端 Notification 本体上线前,message.js 的本地推导仍可用作降级。
 * 上线后把 message.js 的 fetchSystemMessages 改为调本服务即可。
 */

import { OBJECT_TYPES } from '../utils/api'
import { callList, callIdAction, callPayloadAction } from '../utils/request'

/**
 * 查询通知列表
 *
 * @param {object} options
 * @param {string} [options.residentId]  接收居民
 * @param {string} [options.status]      UNREAD / READ / ALL
 * @param {string} [options.notificationType] APPROVAL_RESULT / ATTENDANCE_ALERT / SYSTEM 等
 * @param {object} [options.page]
 */
export function listNotifications({
	residentId,
	status,
	notificationType,
	page = { pageNo: 1, pageSize: 20 }
} = {}) {
	const conditions = []
	if (residentId) {
		conditions.push({ field: 'recipient', operator: 'EQ', value1: residentId })
	}
	if (status && status !== 'ALL') {
		conditions.push({ field: 'status', operator: 'EQ', value1: status })
	}
	if (notificationType) {
		conditions.push({ field: 'notificationType', operator: 'EQ', value1: notificationType })
	}

	return callList(OBJECT_TYPES.notification, {
		selection: 'id,title,content,notificationType,channel,status,readAt,sentAt,bizType,bizRef,handled,createAt',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

/**
 * 标记单条已读
 */
export function markRead(id) {
	return callIdAction('markRead', OBJECT_TYPES.notification, id)
}

/**
 * 全部标记已读
 */
export function markAllRead() {
	return callPayloadAction('markAllRead', OBJECT_TYPES.notification, {})
}

/**
 * 预警类消息轻量处置
 */
export function processNotification(id, handleNote) {
	return callPayloadAction('process', OBJECT_TYPES.notification, { id, handleNote })
}

/**
 * 未读数量
 */
export async function getUnreadCount(residentId) {
	const result = await listNotifications({
		residentId,
		status: 'UNREAD',
		page: { pageNo: 1, pageSize: 1 }
	})
	return (result.page && result.page.total) || result.data.length
}

