		<view class="submit-section" v-if="photoList.length >= 1">
			<button class="submit-btn" hover-class="btn-pressed" @click="submitCheckin">提交打卡</button>
		</view>
	</view>
</template>

<script>
import { uploadAttendanceAttachment, submitAttendance } from '../../services/attendance'
import { getResidentInfo } from '../../services/storage'

export default {
	data() {
		return {
			showCamera: true,
			photoList: [],
			imageClarity: '合格',
			lightLevel: '中等',
			envConsistency: '匹配',
			completeness: '部分缺失',
			locationAddress: '',
			longitude: '0.000',
			latitude: '0.000',
			accuracy: '中等',
			submitting: false
		}
	},
	onLoad() {
		this.getLocation()
	},
	methods: {
		goBack() {
			uni.navigateBack()
		},
		getLocation() {
			uni.getLocation({
				type: 'gcj02',
				success: (res) => {
					this.latitude = res.latitude.toFixed(3)
					this.longitude = res.longitude.toFixed(3)
					this.accuracy = res.accuracy < 50 ? '高' : (res.accuracy < 100 ? '中等' : '低')
				},
				fail: () => {}
			})
		},
		onCameraError() {
			this.showCamera = false
		},
		takePhoto() {
			if (this.photoList.length >= 3) {
				uni.showToast({ title: '最多拍摄3张照片', icon: 'none' })
				return
			}

			// #ifdef MP-WEIXIN
			const ctx = uni.createCameraContext()
			ctx.takePhoto({
				quality: 'high',
				success: (res) => {
					this.photoList.push(res.tempImagePath)
					this.updateIndicators()
				},
				fail: () => this.simulateTakePhoto()
			})
			// #endif

			// #ifndef MP-WEIXIN
			this.simulateTakePhoto()
			// #endif
		},
		simulateTakePhoto() {
			uni.chooseImage({
				count: 1,
				success: (res) => {
					this.photoList.push(res.tempFilePaths[0])
					this.updateIndicators()
				}
			})
		},
		updateIndicators() {
			if (this.photoList.length >= 2) {
				this.completeness = '完整'
				this.envConsistency = '匹配'
			}
			if (this.photoList.length >= 3) {
				this.lightLevel = '充足'
			}
		},
		deletePhoto(index) {
			this.photoList.splice(index, 1)
		},
		async submitCheckin() {
			if (this.submitting) {
				return
			}
			if (!this.photoList.length) {
				uni.showToast({ title: '请至少拍摄一张照片', icon: 'none' })
				return
			}

			const resident = getResidentInfo()
			if (!resident || !resident.id) {
				uni.showModal({
					title: '请先登录',
					content: '尚未识别到居民信息，请重新登录后再打卡。',
					showCancel: false,
					success: () => uni.navigateTo({ url: '/pages/login/login?from=checkin' })
				})
				return
			}

			this.submitting = true
			try {
				const attachments = []
				for (let i = 0; i < this.photoList.length; i += 1) {
					uni.showLoading({ title: `上传照片 ${i + 1}/${this.photoList.length}` })
					const attachment = await uploadAttendanceAttachment(this.photoList[i], 'environment')
					attachments.push(attachment)
				}

				uni.showLoading({ title: '提交打卡中...' })
				await submitAttendance({
					residentId: resident.id,
					attendanceType: 'RESIDENCE',
					environment: attachments[0],
					location: {
						longitude: Number(this.longitude),
						latitude: Number(this.latitude)
					},
					mode: 'MINI_PROGRAM'
				})

				uni.hideLoading()
				uni.showToast({ title: '打卡成功', icon: 'success', duration: 2000 })
				setTimeout(() => uni.navigateBack({ delta: 2 }), 2000)
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '打卡失败', icon: 'none' })
			} finally {
				this.submitting = false
			}
		}
	}
}
</script>

