				<text class="back-icon">&lt;</text>
			</view>
			<text class="header-title">环境记录</text>
			<view class="header-right">
				<text class="photo-count">{{ photoList.length }}/3</text>
			</view>
		</view>-->

		<!-- 拍摄说明 -->
		<view class="tips-card">
			<view class="tips-header">
				<text class="tips-icon">ℹ</text>
				<text class="tips-title">环境拍摄说明</text>
			</view>
			<text class="tips-content">请手持设备缓慢转动360°，确保完整拍摄周围环境。拍摄时请避免人员遮挡或强光直射。</text>
		</view>

		<!-- 相机预览区域 -->
		<view class="camera-section">
