				<camera v-if="showCamera" device-position="back" flash="auto" class="camera" @error="onCameraError"></camera>
				<view v-else class="camera-placeholder">
					<text class="camera-icon">📷</text>
				</view>
			</view>
		</view>

		<!-- 检测指标 -->
		<view class="indicator-section">
			<view class="indicator-grid">
				<view class="indicator-item">
					<text class="indicator-label">图像清晰度</text>
