						<view class="indicator-fill fill-green" style="width: 90%;"></view>
					</view>
				</view>
				<view class="indicator-item">
					<text class="indicator-label">光线充足</text>
					<text class="indicator-value value-orange">{{ lightLevel }}</text>
					<view class="indicator-bar">
						<view class="indicator-fill fill-orange" style="width: 60%;"></view>
					</view>
				</view>
				<view class="indicator-item">
					<text class="indicator-label">环境一致性</text>
					<text class="indicator-value value-green">{{ envConsistency }}</text>
