						<view class="indicator-fill fill-green" style="width: 85%;"></view>
					</view>
				</view>
				<view class="indicator-item">
					<text class="indicator-label">完整性</text>
					<text class="indicator-value value-orange">{{ completeness }}</text>
					<view class="indicator-bar">
						<view class="indicator-fill fill-orange" style="width: 50%;"></view>
