<template>
	<view class="page">


		<view class="content">
			<!-- 请假类型 -->
			<view class="section">
				<text class="section-title">请假类型</text>
				<view class="type-grid" v-if="leaveTypes.length">
					<view
						v-for="item in leaveTypes"
						:key="item.id"
						class="type-item"
						:class="{'type-item-active': leaveType === item.id}"
						@click="selectLeaveType(item.id)"
					>
						<text class="type-text">{{ item.name }}</text>
					</view>
				</view>
				<text class="empty-tip" v-else>{{ leaveTypesLoading ? '加载中…' : '暂无可选类型' }}</text>
			</view>

			<!-- 请假时间 -->
			<view class="section">
				<text class="section-title">请假时间</text>
				<view class="time-row">
					<view class="time-item">
						<text class="time-label">开始时间</text>
						<picker mode="date" :value="startDate" @change="onStartDateChange">
							<view class="time-picker">
								<text class="time-value">{{startDate}}</text>
								<text class="picker-icon">📅</text>
							</view>
						</picker>
					</view>
					<view class="time-item">
						<text class="time-label">结束时间</text>
						<picker mode="date" :value="endDate" @change="onEndDateChange">
							<view class="time-picker">
								<text class="time-value">{{endDate}}</text>
								<text class="picker-icon">📅</text>
							</view>
						</picker>
					</view>
				</view>
			</view>

			<!-- 事由说明 -->
			<view class="section">
				<text class="section-title">事由说明</text>
				<textarea
					class="textarea"
					placeholder="请简要说明请假事由..."
					v-model="reason"
					maxlength="500"
				></textarea>
			</view>

			<!-- 地点信息 -->
			<view class="section">
				<view class="section-header">
					<text class="section-title">地点信息</text>
					<text class="section-tag">选填</text>
					<text class="section-link" @click="captureLocation">{{ locating ? '定位中...' : '自动定位' }}</text>
				</view>
				<view class="input-row">
					<text class="input-icon">📍</text>
					<input
						class="input-field"
						placeholder="请填写请假期间所在地点"
						v-model="location"
					/>
				</view>
				<text class="location-hint" v-if="longitude !== undefined">坐标:{{ longitude }} · {{ latitude }}</text>
			</view>
		</view>

		<!-- 底部按钮 -->
		<view class="footer">
			<button class="footer-btn btn-outline" hover-class="btn-pressed" @click="saveDraft">保存草稿</button>
			<button class="footer-btn btn-primary" hover-class="btn-pressed" @click="submitApplication">提交申请</button>
		</view>
	</view>
</template>

<script>
import { applyLeave, submitLeave, listLeaveTypes } from '../../services/leave'
import { getResidentInfo } from '../../services/storage'
import { unwrapResponseData } from '../../utils/request'

function todayString() {
	const d = new Date()
	const m = (d.getMonth() + 1).toString().padStart(2, '0')
	const day = d.getDate().toString().padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}

export default {
	data() {
		const today = todayString()
		return {
			leaveType: '',
			startDate: today,
			endDate: today,
			reason: '',
			location: '',
			longitude: undefined,
			latitude: undefined,
			locating: false,
			leaveTypes: [],
			leaveTypesLoading: false,
			submitting: false
		}
	},
	onLoad() {
		this.loadDraft()
		this.loadLeaveTypes()
	},
	methods: {
		async loadLeaveTypes() {
			if (this.leaveTypesLoading) {
				return
			}
			this.leaveTypesLoading = true
			try {
				const result = await listLeaveTypes()
				this.leaveTypes = (result.data || []).map((item) => ({
					id: item.id,
					name: item.name,
					code: item.code
				}))
				if (!this.leaveType && this.leaveTypes.length) {
					this.leaveType = this.leaveTypes[0].id
				}
			} catch (error) {
				console.warn('加载请假类型失败', error)
			} finally {
				this.leaveTypesLoading = false
			}
		},
		goBack() {
			uni.navigateBack()
		},
		selectLeaveType(typeId) {
			this.leaveType = typeId
		},
		onStartDateChange(e) {
			this.startDate = e.detail.value
		},
		onEndDateChange(e) {
			this.endDate = e.detail.value
		},
		captureLocation() {
			this.locating = true
			uni.getLocation({
				type: 'gcj02',
				success: (res) => {
					this.longitude = Number(res.longitude.toFixed(6))
					this.latitude = Number(res.latitude.toFixed(6))
					uni.showToast({ title: '已获取定位', icon: 'success' })
				},
				fail: () => {
					uni.showToast({ title: '获取定位失败', icon: 'none' })
				},
				complete: () => {
					this.locating = false
				}
			})
		},
		saveDraft() {
			uni.setStorageSync('leaveDraft', {
				leaveType: this.leaveType,
				startDate: this.startDate,
				endDate: this.endDate,
				reason: this.reason,
				location: this.location,
				savedAt: Date.now()
			})
			uni.showToast({ title: '草稿已保存', icon: 'success' })
		},
		loadDraft() {
			const draft = uni.getStorageSync('leaveDraft')
			if (!draft || typeof draft !== 'object') {
				return
			}
			if (draft.leaveType) this.leaveType = draft.leaveType
			if (draft.startDate) this.startDate = draft.startDate
			if (draft.endDate) this.endDate = draft.endDate
			if (draft.reason) this.reason = draft.reason
			if (draft.location) this.location = draft.location
		},
		async submitApplication() {
			if (this.submitting) {
				return
			}
			if (!this.leaveType) {
				uni.showToast({ title: '请选择请假类型', icon: 'none' })
				return
			}
			if (!this.reason) {
				uni.showToast({ title: '请填写事由说明', icon: 'none' })
				return
			}

			const resident = getResidentInfo()
			if (!resident || !resident.id) {
				uni.showModal({
					title: '请先登录',
					content: '尚未识别到居民信息，请重新登录后再提交。',
					showCancel: false,
					success: () => uni.navigateTo({ url: '/pages/login/login' })
				})
				return
			}

			this.submitting = true
			uni.showLoading({ title: '提交中...' })
			try {
				const addRes = await applyLeave({
					residentId: resident.id,
					leaveTypeId: this.leaveType,
					startDate: this.startDate,
					endDate: this.endDate,
					reason: this.reason
				})
				const created = unwrapResponseData(addRes)
				const id = Array.isArray(created) ? (created[0] && created[0].id) : (created && created.id)
				let submitFailed = false
				if (id) {
					try {
						await submitLeave(id)
					} catch (submitError) {
						submitFailed = true
						console.warn('请假提交审批流失败', submitError)
					}
				}
				uni.hideLoading()
				uni.removeStorageSync('leaveDraft')

				if (submitFailed) {
					uni.showModal({
						title: '提交未完成',
						content: '请假信息已保存为草稿,但提交进入审批流失败,请稍后到「申请记录」页重新提交。',
						showCancel: false,
						success: () => uni.redirectTo({ url: '/pages/history/history' })
					})
					return
				}

				uni.showToast({ title: '申请已提交', icon: 'success' })
				setTimeout(() => uni.redirectTo({ url: '/pages/history/history' }), 1500)
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '提交失败', icon: 'none' })
			} finally {
				this.submitting = false
			}
		}
	}
}
</script>

