<script>
import { submitRecord, submitResidenceChange } from '../../services/record'
import { getResidentInfo } from '../../services/storage'
import { unwrapResponseData } from '../../utils/request'

const DRAFT_KEY_PREFIX = 'recordDraft:'

function todayString(offsetDays = 0) {
	const d = new Date()
	d.setDate(d.getDate() + offsetDays)
	const m = (d.getMonth() + 1).toString().padStart(2, '0')
	const day = d.getDate().toString().padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}

function formatTime(ts) {
	if (!ts) return ''
	const d = new Date(ts)
	if (Number.isNaN(d.getTime())) return ''
	const today = new Date()
	const isToday = d.getFullYear() === today.getFullYear()
		&& d.getMonth() === today.getMonth()
		&& d.getDate() === today.getDate()
	const hh = d.getHours().toString().padStart(2, '0')
	const mm = d.getMinutes().toString().padStart(2, '0')
	if (isToday) {
		return `今天 ${hh}:${mm}`
	}
	const m = (d.getMonth() + 1).toString().padStart(2, '0')
	const day = d.getDate().toString().padStart(2, '0')
	return `${m}-${day} ${hh}:${mm}`
}

export default {
	data() {
		return {
			recordType: 'work',
			startDate: todayString(),
			endDate: todayString(30),
			returnDate: todayString(35),
			address: '',
			workplace: '',
			longitude: undefined,
			latitude: undefined,
			locating: false,
			submitting: false,
			lastSavedAt: 0
		}
	},
	computed: {
		workplaceLabel() {
			return this.recordType === 'work' ? '工作单位/地' : '联系方式或单位'
		},
		workplacePlaceholder() {
			return this.recordType === 'work' ? '请输入工作单位信息,如:某某公司' : '请输入联系方式或单位'
		},
		locationDisplay() {
			if (this.locating) {
				return '定位中...'
			}
			if (this.longitude !== undefined && this.latitude !== undefined) {
				return `经度 ${this.longitude} · 纬度 ${this.latitude}`
			}
			return '未获取到定位'
		},
		hasContent() {
			return !!(this.address || this.workplace)
		},
		lastSavedLabel() {
			return this.lastSavedAt ? `上次保存:${formatTime(this.lastSavedAt)}` : ''
		}
	},
	onLoad() {
		this.loadDraft(this.recordType, true)
		this.captureLocation()
	},
	methods: {
		draftKey(type) {
			return `${DRAFT_KEY_PREFIX}${type || this.recordType}`
		},
		loadDraft(type, silent = false) {
			const draft = uni.getStorageSync(this.draftKey(type))
			if (!draft || typeof draft !== 'object') {
				if (!silent) {
					this.address = ''
					this.workplace = ''
					this.startDate = todayString()
					this.endDate = todayString(30)
					this.returnDate = todayString(35)
				}
				this.lastSavedAt = 0
				return
			}
			this.startDate = draft.startDate || todayString()
			this.endDate = draft.endDate || todayString(30)
			this.returnDate = draft.returnDate || todayString(35)
			this.address = draft.address || ''
			this.workplace = draft.workplace || ''
			this.lastSavedAt = draft.savedAt || 0
			if (!silent && this.lastSavedAt) {
				uni.showToast({ title: '已恢复草稿', icon: 'none' })
			}
		},
		goBack() {
			uni.navigateBack()
		},
		selectRecordType(type) {
			if (this.recordType === type) {
				return
			}
			this.recordType = type
			this.loadDraft(type)
		},
		onStartDateChange(e) {
			this.startDate = e.detail.value
		},
		onEndDateChange(e) {
			this.endDate = e.detail.value
		},
		onReturnDateChange(e) {
			this.returnDate = e.detail.value
		},
		captureLocation() {
			this.locating = true
			uni.getLocation({
				type: 'gcj02',
				success: (res) => {
					this.longitude = Number(res.longitude.toFixed(6))
					this.latitude = Number(res.latitude.toFixed(6))
				},
				fail: () => {
					// 静默,提交时由后端按需校验
				},
				complete: () => {
					this.locating = false
				}
			})
		},
		pickLocation() {
			uni.chooseLocation({
				success: (res) => {
					this.longitude = Number((res.longitude || 0).toFixed(6))
					this.latitude = Number((res.latitude || 0).toFixed(6))
					const detail = res.address || res.name || ''
					if (detail) {
						this.address = res.name && res.address && res.address.indexOf(res.name) === -1
							? `${res.address} ${res.name}`
							: detail
					}
				},
				fail: (err) => {
					if (err && err.errMsg && err.errMsg.includes('cancel')) {
						return
					}
					uni.showToast({ title: '选择地点失败', icon: 'none' })
				}
			})
		},
		saveDraft() {
			if (!this.hasContent) {
				uni.showToast({ title: '请先填写地址或工作信息', icon: 'none' })
				return
			}
			const savedAt = Date.now()
			uni.setStorageSync(this.draftKey(), {
				recordType: this.recordType,
				startDate: this.startDate,
				endDate: this.endDate,
				returnDate: this.returnDate,
				address: this.address,
				workplace: this.workplace,
				savedAt
			})
			this.lastSavedAt = savedAt
			uni.showToast({ title: '草稿已保存', icon: 'success' })
		},
		clearDraft() {
			if (!this.lastSavedAt && !this.hasContent) {
				return
			}
			uni.showModal({
				title: '清除草稿',
				content: `确定清除当前「${this.recordTypeLabel(this.recordType)}」的草稿吗?`,
				success: (res) => {
					if (!res.confirm) {
						return
					}
					uni.removeStorageSync(this.draftKey())
					this.address = ''
					this.workplace = ''
					this.startDate = todayString()
					this.endDate = todayString(30)
					this.returnDate = todayString(35)
					this.lastSavedAt = 0
					uni.showToast({ title: '已清除', icon: 'success' })
				}
			})
		},
		recordTypeLabel(type) {
			return ({ work: '外出打工', temp: '临时外出', long: '长期异地' })[type] || '备案'
		},
		async submitApplication() {
			if (this.submitting) {
				return
			}
			if (!this.address) {
				uni.showToast({ title: '请填写异地居住地址', icon: 'none' })
				return
			}
			if (this.recordType === 'work' && !this.workplace) {
				uni.showToast({ title: '请填写工作单位/地', icon: 'none' })
				return
			}

			const resident = getResidentInfo()
			if (!resident || !resident.id) {
				uni.showModal({
					title: '请先登录',
					content: '尚未识别到居民信息，请重新登录后再提交。',
					showCancel: false,
					success: () => uni.navigateTo({ url: '/pages/login/login' })
				})
				return
			}

			this.submitting = true
			uni.showLoading({ title: '提交中...' })
			try {
				const addRes = await submitRecord({
					recordType: this.recordType,
					residentId: resident.id,
					address: this.address,
					workplace: this.workplace,
					startDate: this.startDate,
					endDate: this.endDate,
					returnDate: this.returnDate,
					longitude: this.longitude,
					latitude: this.latitude
				})
				const created = unwrapResponseData(addRes)
				const id = Array.isArray(created) ? (created[0] && created[0].id) : (created && created.id)
				// 居住变更类备案需要再 submit 进入审批流;外出务工记录通常无审批
				let submitFailed = false
				if (id && this.recordType !== 'work') {
					try {
						await submitResidenceChange(id)
					} catch (submitError) {
						submitFailed = true
						console.warn('备案提交审批流失败', submitError)
					}
				}
				uni.hideLoading()
				uni.removeStorageSync(this.draftKey())
				this.lastSavedAt = 0

				if (submitFailed) {
					uni.showModal({
						title: '提交未完成',
						content: '备案信息已保存为草稿,但提交进入审批流失败,请稍后到「申请记录」页重新提交。',
						showCancel: false,
						success: () => uni.redirectTo({ url: '/pages/history/history' })
					})
					return
				}

				uni.showToast({ title: '备案已提交', icon: 'success' })
				setTimeout(() => uni.redirectTo({ url: '/pages/history/history' }), 1500)
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '提交失败', icon: 'none' })
			} finally {
				this.submitting = false
			}
		}
	}
}
