/**
 * services/attendance.js — 考勤打卡 + 补卡
 *
 * 实体:
 *   - cn.byteawake.prh.Attendance        每日打卡记录
 *   - cn.byteawake.prh.AttendanceMakeup  补卡申请
 */

import { OBJECT_TYPES, UPLOAD_URL } from '../utils/api'
import {
	callPayloadAction,
	callIdAction,
	callList,
	uploadFile
} from '../utils/request'

/**
 * 上传打卡相关附件(人脸照片 / 环境照片或视频),返回 Attachment { name, url, mimeType }
 */
export async function uploadAttendanceAttachment(filePath, kind = 'environment') {
	const response = await uploadFile({
		url: UPLOAD_URL,
		filePath,
		name: 'file',
		formData: {
			bizType: 'attendance',
			kind
		}
	})

	const data = (response && response.data) || response || {}
	return {
		name: data.name || data.fileName || '',
		url: data.url || data.fileUrl || data.fullUrl || data.path || data.filePath || '',
		mimeType: data.mimeType || data.contentType || data.type || ''
	}
}

/**
 * 提交一次打卡
 */
export function submitAttendance(input) {
	const payload = {
		resident: input.residentId,
		attendanceType: input.attendanceType || 'RESIDENCE',
		checkIn: input.checkIn || new Date().toISOString(),
		mode: input.mode || 'MINI_PROGRAM',
		status: 'VALID'
	}

	if (input.face) payload.face = input.face
	if (input.environment) payload.environment = input.environment
	if (input.location) payload.location = input.location
	if (input.deviceId) payload.deviceId = input.deviceId
	if (input.ipAddress) payload.ipAddress = input.ipAddress
	if (input.browser) payload.browser = input.browser

	return callPayloadAction('add', OBJECT_TYPES.attendance, payload)
}

export function listResidentAttendance({ residentId, startDate, endDate, page = { pageNo: 1, pageSize: 20 } } = {}) {
	const conditions = []
	if (residentId) {
		conditions.push({ field: 'resident', operator: 'EQ', value1: residentId })
	}
	if (startDate && endDate) {
		conditions.push({ field: 'checkIn', operator: 'BETWEEN', value1: startDate, value2: endDate })
	}

	return callList(OBJECT_TYPES.attendance, {
		selection: 'id,checkIn,attendanceType,status,mode,deadline',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'checkIn', direction: 'DESC' }],
		page
	})
}

/**
 * 当日是否已打卡
 */
export async function isCheckedInToday(residentId) {
	if (!residentId) {
		return false
	}

	const today = new Date()
	const start = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 0, 0, 0).toISOString()
	const end = new Date(today.getFullYear(), today.getMonth(), today.getDate(), 23, 59, 59).toISOString()

	const result = await listResidentAttendance({
		residentId,
		startDate: start,
		endDate: end,
		page: { pageNo: 1, pageSize: 1 }
	})
	return result.data.some((item) => item.status === 'VALID')
}

export function applyAttendanceMakeup({ residentId, targetAttendanceId, reason }) {
	return callPayloadAction('add', OBJECT_TYPES.attendanceMakeup, {
		resident: residentId,
		targetAttendance: targetAttendanceId,
		reason,
		status: 'DRAFT'
	})
}

export function submitAttendanceMakeup(id) {
	return callIdAction('submit', OBJECT_TYPES.attendanceMakeup, id)
}

