async loadActiveLeave(residentId) {
	try {
		// 查询审批通过且当前日期在请假区间内的记录
		const today = new Date().toISOString().slice(0, 10)
		const result = await listResidentLeaves({
			residentId,
			page: { pageNo: 1, pageSize: 10 }
		})
		// 找到当前生效的请假:已完成(审批通过)且 endDate >= 今天
		const active = result.data.find((item) => {
			if (item.status !== 'COMPLETED') return false
			if (!item.endDate) return true
			return item.endDate >= today
		})
		this.activeLeave = active || null
	} catch (error) {
		this.activeLeave = null
	}
},

