/**
 * 一步提交请假(add + submit 原子操作)
 * 对用户来说只有"提交"一个动作,失败时自动重试 submit 一次
 */
export async function applyAndSubmitLeave(input) {
	const addRes = await applyLeave(input)
	const data = addRes && addRes.data
	const id = Array.isArray(data) ? (data[0] && data[0].id) : (data && data.id)
	if (!id) {
		throw new Error('创建请假记录失败')
	}
	try {
		await submitLeave(id)
	} catch (e) {
		// 重试一次
		await submitLeave(id)
	}
	return id
}

