/**
 * services/leave.js — 请假
 *
 * 实体:
 *   - cn.byteawake.prh.Leave
 *   - cn.byteawake.prh.LeaveType
 */

import { OBJECT_TYPES } from '../utils/api'
import {
	callPayloadAction,
	callIdAction,
	callList
} from '../utils/request'

export function listLeaveTypes() {
	return callList(OBJECT_TYPES.leaveType, {
		selection: 'id,name,code',
		sortItems: [{ path: 'ordinal', direction: 'ASC' }],
		page: { pageNo: 1, pageSize: 50 }
	})
}

/**
 * 新建请假申请
 */
export function applyLeave(input) {
	return callPayloadAction('add', OBJECT_TYPES.leave, {
		resident: input.residentId,
		leaveType: input.leaveTypeId,
		startDate: input.startDate,
		endDate: input.endDate,
		reason: input.reason || '',
		status: 'DRAFT'
	})
}

export function submitLeave(id) {
	return callIdAction('submit', OBJECT_TYPES.leave, id)
}

export function listResidentLeaves({ residentId, status, startDate, endDate, page = { pageNo: 1, pageSize: 20 } } = {}) {
	const conditions = []
	if (residentId) {
		conditions.push({ field: 'resident', operator: 'EQ', value1: residentId })
	}
	if (status) {
		conditions.push({ field: 'status', operator: 'EQ', value1: status })
	}
	if (startDate && endDate) {
		conditions.push({ field: 'startDate', operator: 'BETWEEN', value1: startDate, value2: endDate })
	}

	return callList(OBJECT_TYPES.leave, {
		selection: 'id,leaveType,startDate,endDate,reason,status,createAt',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

