export async function submitRecordAndApprove(input) {
	const addRes = await submitRecord(input)
	const data = addRes && addRes.data
	const id = Array.isArray(data) ? (data[0] && data[0].id) : (data && data.id)
	if (!id) throw new Error('创建备案记录失败')

