/**
 * services/record.js — 居住备案 / 工作备案 / 外出务工备案
 *
 * 实体:
 *   - cn.byteawake.prh.Residence       居住信息(首次登记)
 *   - cn.byteawake.prh.ResidenceChange 居住变更
 *   - cn.byteawake.prh.Employment      工作信息
 *   - cn.byteawake.prh.EmploymentChange工作变更
 *   - cn.byteawake.prh.MigrantWork     外出务工记录
 *
 * UI 备案表单类型 → 本体映射:
 *   work: 外出打工      → MigrantWork
 *   temp: 临时外出      → ResidenceChange (residenceType=OTHER)
 *   long: 长期异地      → ResidenceChange (residenceType=MIGRANT_RENTAL)
 */

import { OBJECT_TYPES } from '../utils/api'
import {
	callPayloadAction,
	callIdAction,
	callList
} from '../utils/request'

function buildAddress({ regionId, detail, longitude, latitude }) {
	const address = {
		region: regionId || '',
		detail: detail || ''
	}
	if (longitude !== undefined && latitude !== undefined) {
		address.geoPoint = { longitude, latitude }
	}
	return address
}

export function submitRecord(input) {
	const {
		recordType,
		residentId,
		address,
		workplace,
		startDate,
		endDate,
		returnDate,
		regionId,
		longitude,
		latitude
	} = input

	const prhAddress = buildAddress({
		regionId,
		detail: address,
		longitude,
		latitude
	})

	if (recordType === 'work') {
		return callPayloadAction('add', OBJECT_TYPES.migrantWork, {
			resident: residentId,
			employer: workplace || '',
			workAddress: prhAddress,
			startDate,
			endDate,
			expectedReturnDate: returnDate
		})
	}

	const residenceType = recordType === 'long' ? 'MIGRANT_RENTAL' : 'OTHER'
	return callPayloadAction('add', OBJECT_TYPES.residenceChange, {
		resident: residentId,
		residenceType,
		address: prhAddress,
		startDate,
		endDate,
		expectedReturnDate: returnDate,
		remark: workplace || ''
	})
}

export function addEmployment(input) {
	return callPayloadAction('add', OBJECT_TYPES.employment, {
		resident: input.residentId,
		employer: input.employer,
		employmentType: input.employmentType,
		address: input.address,
		effectiveDate: input.effectiveDate
	})
}

export function listResidentRecords({ residentId, page = { pageNo: 1, pageSize: 20 } } = {}) {
	const conditions = residentId
		? [{ field: 'resident', operator: 'EQ', value1: residentId }]
		: []

	return callList(OBJECT_TYPES.residenceChange, {
		selection: 'id,residenceType,address,startDate,endDate,status,createAt',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

export function submitResidenceChange(id) {
	return callIdAction('submit', OBJECT_TYPES.residenceChange, id)
}

export function submitMigrantWork(id) {
	return callIdAction('submit', OBJECT_TYPES.migrantWork, id)
}

export function submitEmploymentChange(id) {
	return callIdAction('submit', OBJECT_TYPES.employmentChange, id)
}

/**
 * 查询居民的外出务工记录
 */
export function listMigrantWorks({ residentId, page = { pageNo: 1, pageSize: 20 } } = {}) {
	const conditions = residentId
		? [{ field: 'resident', operator: 'EQ', value1: residentId }]
		: []

	return callList(OBJECT_TYPES.migrantWork, {
		selection: 'id,employer,workAddress,startDate,endDate,status,approvalResult,createAt',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

/**
 * 查询居民的工作变更记录
 */
export function listEmploymentChanges({ residentId, page = { pageNo: 1, pageSize: 20 } } = {}) {
	const conditions = residentId
		? [{ field: 'resident', operator: 'EQ', value1: residentId }]
		: []

	return callList(OBJECT_TYPES.employmentChange, {
		selection: 'id,companyAddress,status,approvalResult,createAt',
		filter: { operator: 'AND', conditions },
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page
	})
}

/**
 * 家庭成员变更申请
 */
export function applyMemberChange({ householdId, memberId, changeType, reason }) {
	return callPayloadAction('add', OBJECT_TYPES.householdMemberChange, {
		household: householdId,
		member: memberId,
		changeType,
		reason: reason || '',
		status: 'DRAFT'
	})
}

export function submitMemberChange(id) {
	return callIdAction('submit', OBJECT_TYPES.householdMemberChange, id)
}

/**
 * 审批通过成员变更(户主确认加入)
 */
export function approveMemberChange(id, opinion) {
	return callPayloadAction('approve', OBJECT_TYPES.householdMemberChange, { id, opinion })
}

/**
 * 审批拒绝成员变更(户主拒绝加入)
 */
export function rejectMemberChange(id, opinion) {
	return callPayloadAction('reject', OBJECT_TYPES.householdMemberChange, { id, opinion })
}

/**
 * 查询家庭待确认的成员变更(户主视角)
 */
export function listPendingMemberChanges(householdId) {
	if (!householdId) return Promise.resolve({ data: [], page: null })

	return callList(OBJECT_TYPES.householdMemberChange, {
		selection: 'id,household,changeType,reason,status,createAt,member',
		filter: {
			operator: 'AND',
			conditions: [
				{ field: 'household', operator: 'EQ', value1: householdId },
				{ field: 'status', operator: 'EQ', value1: 'UNDER_APPROVAL' }
			]
		},
		sortItems: [{ path: 'createAt', direction: 'DESC' }],
		page: { pageNo: 1, pageSize: 20 }
	})
}

