﻿<template>
	<view class="page">
		<!-- Logo区域 -->
		<view class="logo-section">
			<view class="logo-wrapper">
				<image class="logo" src="/static/logo.png" mode="aspectFit"></image>
			</view>
			<text class="app-title">公租房保障监测平台</text>
		</view>

		<!-- 登录表单 -->
		<view class="form-section">
			<!-- 手机号 + 验证码登录 -->
			<block v-if="loginMode === 'sms'">
				<view class="form-item">
					<text class="form-label">手机号码</text>
					<view class="input-wrapper">
						<text class="country-code">+86</text>
						<input
							class="form-input"
							type="number"
							placeholder="请输入手机号"
							v-model="phone"
							maxlength="11"
						/>
					</view>
				</view>

				<view class="form-item">
					<text class="form-label">验证码</text>
					<view class="input-wrapper code-wrapper">
						<input
							class="form-input"
							type="number"
							placeholder="输入验证码"
							v-model="code"
							maxlength="6"
						/>
						<button
							class="code-btn"
							:disabled="countdown > 0"
							@click="sendCode"
						>
							{{countdown > 0 ? `${countdown}s` : '获取验证码'}}
						</button>
					</view>
				</view>
			</block>

			<!-- 账号密码登录 -->
			<block v-else>
				<view class="form-item">
					<text class="form-label">账号</text>
					<view class="input-wrapper">
						<input
							class="form-input"
							placeholder="请输入账号"
							v-model="account"
						/>
					</view>
				</view>

				<view class="form-item">
					<text class="form-label">密码</text>
					<view class="input-wrapper">
						<input
							class="form-input"
							password
							placeholder="请输入密码"
							v-model="password"
						/>
					</view>
				</view>
			</block>

			<!-- 登录按钮 -->
			<button class="login-btn" hover-class="btn-pressed" @click="handleLogin">登录</button>

			<!-- #ifdef MP-WEIXIN -->
			<button class="wechat-btn" open-type="getUserInfo" @getuserinfo="handleWechatUserInfo">
				<text class="wechat-icon">💬</text>
				<text class="wechat-text">微信一键登录</text>
			</button>
			<!-- #endif -->

			<!-- #ifndef MP-WEIXIN -->
			<button class="wechat-btn" @click="startWechatLogin">
				<text class="wechat-icon">💬</text>
				<text class="wechat-text">微信一键登录</text>
			</button>
			<!-- #endif -->

			<!-- 切换登录方式 -->
			<view class="switch-login" @click="switchLoginType">
				<text class="switch-text">{{ loginMode === 'sms' ? '切换至密码登录' : '切换至验证码登录' }}</text>
			</view>
		</view>

		<!-- 底部链接 -->
		<view class="footer-links">
			<text class="link-text" @click="forgotPassword">忘记密码</text>
			<text class="link-text" @click="register">新用户注册</text>
		</view>

		<!-- 版权信息 -->
		<view class="copyright">
			<text class="copyright-text">© 2025 住房保障管理</text>
		</view>
	</view>
</template>

<script>
import { sendSmsOTP, loginByPhone, loginByPassword, loginByWechat } from '../../services/auth'

export default {
	data() {
		return {
			loginMode: 'sms',
			phone: '',
			code: '',
			account: '',
			password: '',
			countdown: 0,
			timer: null,
			from: '',
			submitting: false
		}
	},
	onLoad(options) {
		this.from = options.from || ''
	},
	methods: {
		clearCountdown() {
			if (this.timer) {
				clearInterval(this.timer)
				this.timer = null
			}
			this.countdown = 0
		},
		async sendCode() {
			if (!this.phone || this.phone.length !== 11) {
				uni.showToast({ title: '请输入正确的手机号', icon: 'none' })
				return
			}

			if (this.countdown > 0) {
				return
			}

			try {
				await sendSmsOTP(this.phone)
				this.clearCountdown()
				this.countdown = 60
				this.timer = setInterval(() => {
					this.countdown--
					if (this.countdown <= 0) {
						this.clearCountdown()
					}
				}, 1000)
				uni.showToast({ title: '验证码已发送', icon: 'success' })
			} catch (error) {
				uni.showToast({ title: error.message || '发送验证码失败', icon: 'none' })
			}
		},
		afterLogin(successTitle) {
			this.clearCountdown()
			uni.showToast({ title: successTitle, icon: 'success' })
			setTimeout(() => {
				if (this.from === 'checkin') {
					uni.navigateBack()
					return
				}
				uni.switchTab({ url: '/pages/index/index' })
			}, 1500)
		},
		async handleLogin() {
			if (this.submitting) {
				return
			}

			if (this.loginMode === 'password') {
				if (!this.account) {
					uni.showToast({ title: '请输入账号', icon: 'none' })
					return
				}
				if (!this.password) {
					uni.showToast({ title: '请输入密码', icon: 'none' })
					return
				}

				this.submitting = true
				uni.showLoading({ title: '登录中...' })
				try {
					await loginByPassword({ account: this.account, password: this.password })
					uni.hideLoading()
					this.afterLogin('登录成功')
				} catch (error) {
					uni.hideLoading()
					uni.showToast({ title: error.message || '登录失败', icon: 'none' })
				} finally {
					this.submitting = false
				}
				return
			}

			if (!this.phone || this.phone.length !== 11) {
				uni.showToast({ title: '请输入正确的手机号', icon: 'none' })
				return
			}
			if (!this.code) {
				uni.showToast({ title: '请输入验证码', icon: 'none' })
				return
			}

			this.submitting = true
			uni.showLoading({ title: '登录中...' })
			try {
				await loginByPhone({ phone: this.phone, code: this.code })
				uni.hideLoading()
				this.afterLogin('登录成功')
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '登录失败', icon: 'none' })
			} finally {
				this.submitting = false
			}
		},
		async handleWechatUserInfo(event) {
			const detail = event && event.detail ? event.detail : {}
			if (!detail.userInfo) {
				const message = detail.errMsg && detail.errMsg.includes('deny')
					? '您已取消微信授权'
					: (detail.errMsg || '获取微信用户信息失败')
				uni.showToast({ title: message, icon: 'none' })
				return
			}

			uni.showLoading({ title: '登录中...' })
			try {
				await loginByWechat(detail.userInfo)
				uni.hideLoading()
				this.afterLogin('微信登录成功')
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '微信登录失败', icon: 'none' })
			}
		},
		startWechatLogin() {
			// #ifndef MP-WEIXIN
			uni.showToast({ title: '请在微信小程序中使用', icon: 'none' })
			// #endif
		},
		switchLoginType() {
			this.loginMode = this.loginMode === 'sms' ? 'password' : 'sms'
			this.code = ''
			this.password = ''
			this.clearCountdown()
		},
		forgotPassword() {
			uni.showModal({
				title: '忘记密码',
				content: '请联系所在街道管理员重置密码,或使用手机验证码登录。',
				showCancel: false
			})
		},
		register() {
			uni.showModal({
				title: '新用户注册',
				content: '本系统由街道社区为您统一开通账号,请联系所在管理处。',
				showCancel: false
			})
		}
	},
	beforeUnmount() {
		this.clearCountdown && this.clearCountdown()
	},
	beforeDestroy() {
		this.clearCountdown && this.clearCountdown()
	}
}
