			<text class="copyright-text">© 2025 住房保障管理</text>
		</view>
	</view>
</template>

<script>
import { sendSmsOTP, loginByPhone, loginByPassword, loginByWechat } from '../../services/auth'

export default {
	data() {
		return {
			loginMode: 'sms',
			phone: '',
			code: '',
			account: '',
			password: '',
			countdown: 0,
			timer: null,
			from: '',
			submitting: false
		}
	},
	onLoad(options) {
		this.from = options.from || ''
	},
	methods: {
		clearCountdown() {
			if (this.timer) {
				clearInterval(this.timer)
				this.timer = null
			}
			this.countdown = 0
		},
		async sendCode() {
			if (!this.phone || this.phone.length !== 11) {
				uni.showToast({ title: '请输入正确的手机号', icon: 'none' })
				return
			}

			if (this.countdown > 0) {
				return
			}

			try {
				await sendSmsOTP(this.phone)
				this.clearCountdown()
				this.countdown = 60
				this.timer = setInterval(() => {
					this.countdown--
					if (this.countdown <= 0) {
						this.clearCountdown()
					}
				}, 1000)
				uni.showToast({ title: '验证码已发送', icon: 'success' })
			} catch (error) {
				uni.showToast({ title: error.message || '发送验证码失败', icon: 'none' })
			}
		},
		afterLogin(successTitle) {
			this.clearCountdown()
			uni.showToast({ title: successTitle, icon: 'success' })
			setTimeout(() => {
				if (this.from === 'checkin') {
					uni.navigateBack()
					return
				}
				uni.switchTab({ url: '/pages/index/index' })
			}, 1500)
		},
		async handleLogin() {
			if (this.submitting) {
				return
			}

			if (this.loginMode === 'password') {
				if (!this.account) {
					uni.showToast({ title: '请输入账号', icon: 'none' })
					return
				}
				if (!this.password) {
					uni.showToast({ title: '请输入密码', icon: 'none' })
					return
				}

				this.submitting = true
				uni.showLoading({ title: '登录中...' })
				try {
					await loginByPassword({ account: this.account, password: this.password })
					uni.hideLoading()
					this.afterLogin('登录成功')
				} catch (error) {
					uni.hideLoading()
					uni.showToast({ title: error.message || '登录失败', icon: 'none' })
				} finally {
					this.submitting = false
				}
				return
			}

			if (!this.phone || this.phone.length !== 11) {
				uni.showToast({ title: '请输入正确的手机号', icon: 'none' })
				return
			}
			if (!this.code) {
				uni.showToast({ title: '请输入验证码', icon: 'none' })
				return
			}

			this.submitting = true
			uni.showLoading({ title: '登录中...' })
			try {
				await loginByPhone({ phone: this.phone, code: this.code })
				uni.hideLoading()
				this.afterLogin('登录成功')
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '登录失败', icon: 'none' })
			} finally {
				this.submitting = false
			}
		},
		async handleWechatUserInfo(event) {
			const detail = event && event.detail ? event.detail : {}
			if (!detail.userInfo) {
				const message = detail.errMsg && detail.errMsg.includes('deny')
					? '您已取消微信授权'
					: (detail.errMsg || '获取微信用户信息失败')
				uni.showToast({ title: message, icon: 'none' })
				return
			}

			uni.showLoading({ title: '登录中...' })
			try {
				await loginByWechat(detail.userInfo)
				uni.hideLoading()
				this.afterLogin('微信登录成功')
			} catch (error) {
				uni.hideLoading()
				uni.showToast({ title: error.message || '微信登录失败', icon: 'none' })
			}
		},
		startWechatLogin() {
			// #ifndef MP-WEIXIN
			uni.showToast({ title: '请在微信小程序中使用', icon: 'none' })
			// #endif
		},
		switchLoginType() {
			this.loginMode = this.loginMode === 'sms' ? 'password' : 'sms'
			this.code = ''
			this.password = ''
			this.clearCountdown()
		},
		forgotPassword() {
			uni.showModal({
				title: '忘记密码',
				content: '请联系所在街道管理员重置密码,或使用手机验证码登录。',
				showCancel: false
			})
		},
		register() {
			uni.showModal({
				title: '新用户注册',
				content: '本系统由街道社区为您统一开通账号,请联系所在管理处。',
				showCancel: false
			})
		}
	},
	beforeUnmount() {
		this.clearCountdown && this.clearCountdown()
	},
	beforeDestroy() {
		this.clearCountdown && this.clearCountdown()
	}
}
</script>

