<script>
import { fetchMessages } from '../../services/message'
import { getResidentInfo } from '../../services/storage'

const TIME_RANGE_LABELS = {
	all: '全部',
	week: '近一周',
	month: '近一月',
	three: '近三月'
}

const TIME_RANGE_DAYS = {
	week: 7,
	month: 30,
	three: 90
}

const READ_KEY = 'messageReadIds'
const DELETED_KEY = 'messageDeletedIds'
const PUSH_SETTINGS_KEY = 'messagePushSettings'

const DEFAULT_PUSH_SETTINGS = {
	system: true,
	approval: true,
	reminder: true,
	sound: true,
	vibrate: true
}

const SETTING_ITEMS = [
	{ key: 'system', name: '系统通知', desc: '维护、版本更新等系统消息' },
	{ key: 'approval', name: '审批结果', desc: '请假、备案等审批通知' },
	{ key: 'reminder', name: '预警提醒', desc: '打卡缺勤、备案到期等提醒' },
	{ key: 'sound', name: '声音', desc: '收到推送时播放提示音' },
	{ key: 'vibrate', name: '振动', desc: '收到推送时震动提醒' }
]

function readStorageArray(key) {
	const value = uni.getStorageSync(key)
	if (Array.isArray(value)) {
		return value
	}
	if (typeof value === 'string' && value) {
		try {
			const parsed = JSON.parse(value)
			return Array.isArray(parsed) ? parsed : []
		} catch (error) {
			return []
		}
	}
	return []
}

function readStorageObject(key, fallback) {
	const value = uni.getStorageSync(key)
	if (value && typeof value === 'object' && !Array.isArray(value)) {
		return { ...fallback, ...value }
	}
	if (typeof value === 'string' && value) {
		try {
			const parsed = JSON.parse(value)
			if (parsed && typeof parsed === 'object') {
				return { ...fallback, ...parsed }
			}
		} catch (error) {
			// noop
		}
	}
	return { ...fallback }
}

function parseTime(value) {
	if (!value) {
		return 0
	}
	const t = new Date(value).getTime()
	return Number.isNaN(t) ? 0 : t
}

export default {
	data() {
		return {
			activeTab: 'all',
			searchText: '',
			messages: [],
			loading: false,
			timeRange: 'all',
			selectionMode: false,
			selectedIds: [],
			readIds: [],
			deletedIds: [],
			showSettings: false,
			pushSettings: { ...DEFAULT_PUSH_SETTINGS },
			settingItems: SETTING_ITEMS
		}
	},
	computed: {
		timeRangeLabel() {
			return TIME_RANGE_LABELS[this.timeRange] || '全部'
		},
		visibleMessages() {
			const deleted = new Set(this.deletedIds)
			return this.messages.filter((msg) => !deleted.has(msg.id))
		},
		filteredMessages() {
			const keyword = (this.searchText || '').trim().toLowerCase()
			const days = TIME_RANGE_DAYS[this.timeRange]
			const cutoff = days ? Date.now() - days * 86400000 : 0

			return this.visibleMessages.filter((msg) => {
				if (cutoff && parseTime(msg.time) < cutoff) {
					return false
				}
				if (!keyword) {
					return true
				}
				const haystack = `${msg.title || ''} ${msg.desc || ''}`.toLowerCase()
				return haystack.indexOf(keyword) !== -1
			})
		},
		allSelected() {
			return this.filteredMessages.length > 0
				&& this.filteredMessages.every((msg) => this.selectedIds.indexOf(msg.id) !== -1)
		}
	},
	onLoad() {
		this.loadLocalState()
		this.loadMessages()
	},
	onShow() {
		this.loadMessages()
	},
	methods: {
		loadLocalState() {
			this.readIds = readStorageArray(READ_KEY)
			this.deletedIds = readStorageArray(DELETED_KEY)
			this.pushSettings = readStorageObject(PUSH_SETTINGS_KEY, DEFAULT_PUSH_SETTINGS)
		},
		async loadMessages() {
			if (this.loading) {
				return
			}
			const resident = getResidentInfo()
			this.loading = true
			try {
				this.messages = await fetchMessages({
					tab: this.activeTab,
					residentId: resident && resident.id,
					householdId: resident && resident.householdId
				})
			} catch (error) {
				uni.showToast({ title: error.message || '加载失败', icon: 'none' })
			} finally {
				this.loading = false
			}
		},
		selectTab(tab) {
			this.activeTab = tab
			this.exitSelection()
			this.loadMessages()
		},
		isRead(msg) {
			return this.readIds.indexOf(msg.id) !== -1
		},
		isSelected(msg) {
			return this.selectedIds.indexOf(msg.id) !== -1
		},
		messageIconClass(msg) {
			return {
				'icon-warning': msg.variant === 'warning',
				'icon-success': msg.variant === 'success',
				'icon-alert': msg.variant === 'alert',
				'icon-info': msg.variant === 'info' || !msg.variant
			}
		},
		messageEmoji(msg) {
			if (msg.variant === 'success') return '✅'
			if (msg.variant === 'alert') return '⚠️'
			if (msg.variant === 'warning') return '🔔'
			return '📋'
		},
		onItemTap(msg) {
			if (this.selectionMode) {
				const idx = this.selectedIds.indexOf(msg.id)
				if (idx === -1) {
					this.selectedIds = this.selectedIds.concat([msg.id])
				} else {
					this.selectedIds = this.selectedIds.filter((id) => id !== msg.id)
				}
				return
			}
			this.markRead([msg.id])
		},
		markRead(ids) {
			if (!ids || !ids.length) {
				return
			}
			const set = new Set(this.readIds)
			ids.forEach((id) => set.add(id))
			this.readIds = Array.from(set)
			uni.setStorageSync(READ_KEY, this.readIds)
		},

		// 批量编辑
		batchEdit() {
			if (!this.filteredMessages.length) {
				uni.showToast({ title: '当前列表为空', icon: 'none' })
				return
			}
			this.selectionMode = true
			this.selectedIds = []
		},
		exitSelection() {
			this.selectionMode = false
			this.selectedIds = []
		},
		toggleSelectAll() {
			if (this.allSelected) {
				this.selectedIds = []
			} else {
				this.selectedIds = this.filteredMessages.map((msg) => msg.id)
			}
		},
		markSelectedRead() {
			if (!this.selectedIds.length) {
				uni.showToast({ title: '请先选择消息', icon: 'none' })
				return
			}
			this.markRead(this.selectedIds)
			uni.showToast({ title: `已标记 ${this.selectedIds.length} 条已读`, icon: 'success' })
			this.exitSelection()
		},
		deleteSelected() {
			if (!this.selectedIds.length) {
				uni.showToast({ title: '请先选择消息', icon: 'none' })
				return
			}
			uni.showModal({
				title: '删除消息',
				content: `确定删除选中的 ${this.selectedIds.length} 条消息吗?`,
				success: (res) => {
					if (!res.confirm) {
						return
					}
					const set = new Set(this.deletedIds)
					this.selectedIds.forEach((id) => set.add(id))
					this.deletedIds = Array.from(set)
					uni.setStorageSync(DELETED_KEY, this.deletedIds)
					uni.showToast({ title: '已删除', icon: 'success' })
					this.exitSelection()
				}
			})
		},

		// 时间筛选
		filterMessages() {
			uni.showActionSheet({
				itemList: ['全部', '近一周', '近一月', '近三月'],
				success: (res) => {
					const map = ['all', 'week', 'month', 'three']
					this.setTimeRange(map[res.tapIndex] || 'all')
				}
			})
		},
		setTimeRange(range) {
			this.timeRange = range
		},

		// 推送设置
		openSettings() {
			this.showSettings = true
		},
		closeSettings() {
			this.showSettings = false
			uni.setStorageSync(PUSH_SETTINGS_KEY, this.pushSettings)
		},
		onSettingChange(key, event) {
			const value = !!(event && event.detail && event.detail.value)
			this.pushSettings = { ...this.pushSettings, [key]: value }
			uni.setStorageSync(PUSH_SETTINGS_KEY, this.pushSettings)
		}
	}
}
</script>

