/**
 * 公租房保障监测系统 — 全局样式变量
 *
 * 配色方案: 政务深蓝
 * 主色: #1e3a5f (藏蓝) — 庄重、可信赖
 * 辅助操作色: #2563eb — 按钮、链接等交互元素
 */

/* ========== 业务色板 ========== */

/* 主色系(藏蓝) */
$color-primary: #1e3a5f;
$color-primary-light: #2d5a8e;
$color-primary-dark: #152a45;
$color-primary-bg: #eef3f9;

