$color-bg-hover: #e2e8f0;

$color-border: #e2e8f0;
$color-border-light: #f1f5f9;
$color-divider: rgba(30, 58, 95, 0.06);

/* 渐变 */
$gradient-header: linear-gradient(135deg, #1e3a5f 0%, #2d5a8e 100%);
$gradient-button: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%);

/* ========== uni-app 内置变量覆盖 ========== */

$uni-color-primary: #1e3a5f;
$uni-color-success: #16a34a;
$uni-color-warning: #d97706;
$uni-color-error: #dc2626;

$uni-text-color: #1e293b;
$uni-text-color-inverse: #fff;
$uni-text-color-grey: #94a3b8;
$uni-text-color-placeholder: #94a3b8;
$uni-text-color-disable: #cbd5e1;

$uni-bg-color: #ffffff;
$uni-bg-color-grey: #f8fafc;
$uni-bg-color-hover: #e2e8f0;
$uni-bg-color-mask: rgba(0, 0, 0, 0.5);

$uni-border-color: #e2e8f0;

/* 尺寸变量 */
$uni-font-size-sm: 12px;
$uni-font-size-base: 14px;
$uni-font-size-lg: 16px;

$uni-img-size-sm: 20px;
$uni-img-size-base: 26px;
$uni-img-size-lg: 40px;

$uni-border-radius-sm: 2px;
$uni-border-radius-base: 3px;
$uni-border-radius-lg: 6px;
$uni-border-radius-circle: 50%;

$uni-spacing-row-sm: 5px;
$uni-spacing-row-base: 10px;
$uni-spacing-row-lg: 15px;

$uni-spacing-col-sm: 4px;
$uni-spacing-col-base: 8px;
$uni-spacing-col-lg: 12px;

$uni-opacity-disabled: 0.3;

