=== global.less ===
@font-face {
  font-family: "AlibabaSans";
  font-style: normal;
  font-weight: 300;
  font-display: swap;
  src: url("//mdn.alipayobjects.com/huamei_iwk9zp/afts/file/A*1GSgSYDD_aIAAAAAQsAAAAgAegCCAQ/AlibabaSans-Light.woff2")
    format("woff2");
}
@font-face {
  font-family: "AlibabaSans";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("//mdn.alipayobjects.com/huamei_iwk9zp/afts/file/A*2zEUQqnPNesAAAAAQtAAAAgAegCCAQ/AlibabaSans-Regular.woff2")
    format("woff2");
}
@font-face {
  font-family: "AlibabaSans";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("//mdn.alipayobjects.com/huamei_iwk9zp/afts/file/A*E_cxRbMlZqUAAAAAQuAAAAgAegCCAQ/AlibabaSans-Medium.woff2")
    format("woff2");
}
@font-face {
  font-family: "AlibabaSans";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("//mdn.alipayobjects.com/huamei_iwk9zp/afts/file/A*E_cxRbMlZqUAAAAAQuAAAAgAegCCAQ/AlibabaSans-Bold.woff2")
    format("woff2");
}
@font-face {
  font-family: "AlibabaSans";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("//mdn.alipayobjects.com/huamei_iwk9zp/afts/file/A*E_cxRbMlZqUAAAAAQuAAAAgAegCCAQ/AlibabaSans-Heavy.woff2")
    format("woff2");
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  padding: 0;
  font-family:
    AlibabaSans, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';
}

.colorWeak {
  filter: invert(80%);
}

.ant-layout {
  min-height: 100vh;
}
.ant-pro-sider.ant-layout-sider.ant-pro-sider-fixed {
  left: unset;
}

canvas {
  display: block;
}

body {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

ul,
ol {
  list-style: none;
}

@media (max-width: 768px) {
  .ant-table {
    width: 100%;
    overflow-x: auto;
    &-thead > tr,
    &-tbody > tr {
      > th,
      > td {
        white-space: pre;
        > span {
          display: block;
        }
      }
    }
  }
}

/*
 * 搜索/工具栏折行间距
 *
 * 1) `<Space wrap>` 在 antd 5 默认 row-gap = size(small=8px),折行后看着挤,
 *    全局调整为 12px,Personnel/Menu/Role 等使用 Space wrap 的搜索栏受益。
 * 2) `<Form layout="inline">` 折行时 Form.Item 自带 24px 下间距,
 *    单行偏大、多行偏小,统一改成 row-gap=12px + Item margin-bottom=0,
 *    与上面一致;最后一组按钮(查询/重置)就不会再紧贴上一行。
 */
.ant-space-wrap {
  row-gap: 12px !important;
}

.ant-form-inline {
  row-gap: 12px;

  & > .ant-form-item {
    margin-bottom: 0;
    margin-right: 16px;
  }
}

/*
 * 主从布局工具栏专属:Card body 内 inline Form 上下留白
 * 因为 Card body 已经有 14/12 padding,Form 内部如果折行,row-gap 仍生效
 */
.ant-card-small > .ant-card-body .ant-form-inline {
  row-gap: 14px;
}

/*
 * PC 大屏视觉间距统一:行高 / Card 边距
 *
 * 用户场景仅 PC + 大屏平板,信息密度可以适当拉开。
 * - 表格行高从默认 ~54px 提升到 ~58px(数据行更易读)
 * - Card 内 padding 保持 antd 默认 24,Card 之间间距统一 20
 */
.ant-table-cell {
  padding-top: 16px !important;
  padding-bottom: 16px !important;
}

/* 主从布局:列表行选中态高亮(替代 antd 默认浅蓝,与本项目主色更协调) */
.master-list-row-selected,
.master-list-row-selected > td {
  background: color-mix(in srgb, var(--ant-color-primary) 12%, transparent) !important;
}

.master-list-row-selected:hover > td {
  background: color-mix(in srgb, var(--ant-color-primary) 22%, transparent) !important;
}

/* 主从布局:分隔条 hover 高亮 */
.md-splitter:hover .md-splitter-line {
  background: var(--ant-color-primary) !important;
}

.md-splitter:hover .md-splitter-handle {
  border-color: var(--ant-color-primary) !important;
  box-shadow: 0 2px 8px color-mix(in srgb, var(--ant-color-primary) 25%, transparent) !important;
}

/*
 * Layout: Header 项目名 logo 区(可点击切换左 rail)
 * - hover 浅灰反馈
 */
.layout-brand:hover {
  opacity: 0.78;
}
.layout-brand:active {
  opacity: 0.65;
}

/*
 * Layout: Tab 栏(鱼鳍风) — 借鉴 OMS 原型
 * - 容器灰色底 + 主色 10% 底边
 * - 单 Tab 30px 高、圆角顶、active 主色 10% 背景 + 主色文字
 * - active 左右底部用 radial-gradient 做切角
 * - X 按钮默认隐藏,hover/active 才显
 */
.app-layout-tabbar {
  border-bottom: 1px solid color-mix(in srgb, var(--ant-color-primary) 12%, transparent);
}
.app-layout-tabs.ant-tabs {
  /* 容器整体 */
  .ant-tabs-nav {
    margin: 0;
    height: 36px;
    min-height: 36px;
  }
  .ant-tabs-nav::before {
    display: none;
  }
  .ant-tabs-nav-list {
    align-items: flex-end;
    gap: 2px;
  }

  /* 单个 Tab 卡片 */
  .ant-tabs-tab {
    height: 30px;
    margin: 0 !important;
    padding: 0 12px 0 10px !important;
    border: 0 !important;
    background: transparent !important;
    border-radius: 8px 8px 0 0 !important;
    font-size: 12px;
    color: var(--ant-color-text-secondary) !important;
    transition: background 0.15s ease, color 0.15s ease;
    position: relative;
  }
  .ant-tabs-tab:hover {
    background: var(--ant-color-fill-tertiary) !important;
    color: var(--ant-color-text) !important;
  }
  .ant-tabs-tab-active {
    background: color-mix(in srgb, var(--ant-color-primary) 10%, transparent) !important;
    border-radius: 10px 10px 0 0 !important;
    overflow: visible !important;
  }
  .ant-tabs-tab-active .ant-tabs-tab-btn {
    color: var(--ant-color-primary) !important;
    font-weight: 600 !important;
  }
  /* 鱼鳍切角:active tab 左右底部用 radial-gradient 做出弧形 */
  .ant-tabs-tab-active::before,
  .ant-tabs-tab-active::after {
    content: '';
    position: absolute;
    bottom: 0;
    width: 10px;
    height: 10px;
    pointer-events: none;
  }
  .ant-tabs-tab-active::before {
    left: -10px;
    background: radial-gradient(
      circle at 0 0,
      transparent 10px,
      color-mix(in srgb, var(--ant-color-primary) 10%, transparent) 10px
    );
  }
  .ant-tabs-tab-active::after {
    right: -10px;
    background: radial-gradient(
      circle at 100% 0,
      transparent 10px,
      color-mix(in srgb, var(--ant-color-primary) 10%, transparent) 10px
    );
  }

  /* X 关闭按钮:默认隐藏,hover/active 显示 */
  .ant-tabs-tab .ant-tabs-tab-remove {
    margin-left: 6px;
    opacity: 0;
    transition: opacity 0.15s ease, background 0.15s ease;
    color: inherit !important;
    width: 16px;
    height: 16px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
  }
  .ant-tabs-tab:hover .ant-tabs-tab-remove,
  .ant-tabs-tab-active .ant-tabs-tab-remove {
    opacity: 1;
  }
  .ant-tabs-tab-remove:hover {
    background: var(--ant-color-fill-tertiary);
  }

  /* 隐藏底部 ink-bar(card 模式不需要) */
  .ant-tabs-ink-bar {
    display: none !important;
  }
}

/*
 * Layout: 左侧主菜单 inline item — 紧凑 + 选中态左 3px 主色边
 */
.ant-layout-sider .ant-menu-inline > .ant-menu-item,
.ant-layout-sider .ant-menu-inline .ant-menu-submenu-title {
  height: 36px !important;
  line-height: 36px !important;
  margin-block: 2px !important;
}
.ant-layout-sider .ant-menu-inline .ant-menu-item-selected {
  position: relative;
}
.ant-layout-sider .ant-menu-inline .ant-menu-item-selected::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 3px;
  background: var(--ant-color-primary);
  border-radius: 0 2px 2px 0;
}

/*
 * 暗色模式兜底:html[data-theme=dark] 时 body 背景跟随 antd 暗色 layout token,
 * 避免登录页等不在 BasicLayout 下的页面闪白。
 */
html[data-theme='dark'] body {
  background: #141414;
  color: rgba(255, 255, 255, 0.85);
}

/* ============ 审批面板(详情页右侧)============ */
.ap-panel-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--ant-color-text);
  margin-bottom: 8px;
}
.ap-timeline {
  position: relative;
}
.ap-timeline-item {
  display: flex;
  gap: 10px;
}
.ap-timeline-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 18px;
  flex-shrink: 0;
}
.ap-timeline-dot {
  font-size: 16px;
  line-height: 1;
  margin-top: 2px;
}
.ap-timeline-line {
  flex: 1;
  width: 2px;
  background: var(--ant-color-border-secondary, #f0f0f0);
  margin: 4px 0;
  min-height: 16px;
}
.ap-timeline-body {
  flex: 1;
  padding-bottom: 18px;
}
.ap-timeline-time {
  font-size: 12px;
  color: var(--ant-color-text-tertiary, #8c8c8c);
  margin-bottom: 2px;
}
.ap-timeline-title {
  font-size: 13px;
  color: var(--ant-color-text);
  margin-bottom: 6px;
}
.ap-timeline-opinion {
  font-size: 13px;
  color: var(--ant-color-text-secondary, #595959);
  background: var(--ant-color-fill-quaternary, #fafafa);
  border: 1px solid var(--ant-color-border-secondary, #f0f0f0);
  border-radius: 6px;
  padding: 8px 12px;
}

/* ============ 全局表格表头样式(对齐 OMS 原型 Tabler thead)============ */
/* 让未走 OmnibarPage 的 antd Table 表头也统一:浅灰底 + 小号 + 弱灰字 */
.ant-table-thead > tr > th {
  background: #ebedf0 !important;
  color: rgba(0, 0, 0, 0.55) !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 0.04em !important;
  line-height: 16px !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.12) !important;
}
/* 暗色模式 */
[data-theme='dark'] .ant-table-thead > tr > th,
.dark .ant-table-thead > tr > th {
  background: #1f1f1f !important;
  color: rgba(255, 255, 255, 0.5) !important;
  border-bottom-color: rgba(255, 255, 255, 0.12) !important;
}

=== Dashboard/index.less ===
// Dashboard 容器
// 不设 min-height,让内容自然高度(BasicLayout 的 Content 已带 overflow: auto)
// max-width 1320px 居中(对齐 OMS 原型 .container-xl,大屏不会拉满)
// 内 padding 由 BasicLayout 统一管理(10px),这里不再设
.dashboard-container {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0;
  background: transparent;
}

// =================== 顶部欢迎行 ===================
//
// 左:欢迎卡(大标题 + 副文案 + 2 个内嵌 mini-stat + 操作按钮)
// 右:4 张业务 stat 小卡(配色方头像 + 大数字 + 副文案)
.welcome-card {
  border-radius: 12px;
  overflow: hidden;
  background: #fff;
  color: rgba(0, 0, 0, 0.85);
  border: 0;
  box-shadow: 0 1px 2px rgba(18, 18, 23, 0.05);
  height: 100%;

  :global {
    .ant-card-body {
      padding: 24px 28px !important;
      height: 100%;
    }
  }

  .welcome-body {
    display: grid;
    grid-template-columns: 1fr 220px;
    gap: 24px;
    align-items: center;
    height: 100%;
    min-height: 168px;
  }

  .welcome-text {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .welcome-greeting {
    font-size: 22px;
    font-weight: 700;
    line-height: 1.2;
    color: #1f1f1f;
  }

  .welcome-subtitle {
    font-size: 13px;
    color: #595959;
    line-height: 1.6;
  }

  .welcome-mini-stats {
    display: flex;
    gap: 32px;
    margin-top: 8px;
  }

  .mini-stat {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .mini-label {
    font-size: 12px;
    color: #8c8c8c;
  }

  .mini-value-row {
    display: flex;
    align-items: baseline;
    gap: 8px;
  }

  .mini-value {
    font-size: 22px;
    font-weight: 700;
    color: #1f1f1f;
    line-height: 1;
  }

  .mini-trend {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    font-size: 12px;
    font-weight: 600;
    line-height: 1;

    &.trend-up {
      color: #389e0d;
    }
    &.trend-down {
      color: #cf1322;
    }
    &.trend-flat {
      color: #8c8c8c;
    }
  }

  .welcome-actions {
    display: flex;
    gap: 8px;
    margin-top: 4px;

    :global(.ant-btn) {
      border-radius: 6px;
    }
  }

  // 右侧业务图标网格 — 2x2,4 块
  .welcome-illustration {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    grid-template-rows: repeat(2, 1fr);
    gap: 8px;
    height: 168px;

    .illu-tile {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 2px;
      border-radius: 10px;
      padding: 10px 6px;
      background: rgba(0, 0, 0, 0.03);
      transition: background 0.15s ease;

      :global(.anticon) {
        font-size: 18px;
        margin-bottom: 2px;
      }
    }
    .illu-num {
      font-size: 18px;
      font-weight: 600;
      line-height: 1;
      color: var(--ant-color-text, #1f1f1f);
    }
    .illu-label {
      font-size: 11px;
      color: #8c8c8c;
      line-height: 1.2;
    }
    /* 统一克制风:不再一格一色,均用淡灰底 + 主色图标 */
    .illu-blue,
    .illu-red,
    .illu-purple,
    .illu-orange {
      background: rgba(0, 0, 0, 0.03);
      :global(.anticon) {
        color: var(--ant-color-primary, #1677ff);
      }
    }
  }
}

// 4 张业务 stat 小卡 — 对齐 Tabler card-sm 风格
// 图标方块(avatar avatar-square) + 中等字重主标题 + 副文案
.stat-mini {
  border-radius: 8px;
  cursor: pointer;
  transition: box-shadow 0.2s ease;

  &:hover {
    box-shadow: 0 4px 12px rgba(18, 18, 23, 0.06);
  }

  :global {
    .ant-card-body {
      padding: 12px 14px !important;
    }
  }

  .stat-mini-row {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  // 方形彩色头像(对齐 .avatar-square 36×36 + 4px 圆角)
  .stat-mini-icon {
    flex-shrink: 0;
    width: 36px;
    height: 36px;
    border-radius: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 18px;
  }

  .stat-mini-text {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0;
  }

  // 主标题:fw-medium(500) + 14px,不是大数字
  .stat-mini-title {
    font-size: 14px;
    font-weight: 500;
    color: #262626;
    line-height: 1.4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  // 副文案:text-secondary 灰 + 13px
  .stat-mini-sub {
    font-size: 13px;
    color: #8c8c8c;
    line-height: 1.4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

// =================== KPI 卡片(借鉴 OMS 原型) ===================
//
// 范式:左上 subheader 灰标签 → 右上彩色涨跌徽章 → 大粗数字 32px →
//       副文案 → 卡片底部 sparkline 占满宽度,不占行高
.kpi-card {
  border-radius: 8px;
  overflow: hidden;
  transition: box-shadow 0.2s ease, transform 0.2s ease;
  height: 100%;

  &:hover {
    box-shadow: 0 4px 12px rgba(18, 18, 23, 0.08), 0 10px 15px -3px rgba(18, 18, 23, 0.06);
  }

  :global {
