function buildSvg(pathData, color) {
	const c = color || '#1e293b'
	const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="${c}" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${pathData}"/></svg>`
	return 'data:image/svg+xml;base64,' + uni.arrayBufferToBase64(
		new Uint8Array(Array.from(svg).map(ch => ch.charCodeAt(0)))
	)
}

