2	import { getToken } from './services/storage'
3	
4	const LOGIN_PAGE = '/pages/login/login'
5	
6	const NO_AUTH_PAGES = [
7		'pages/login/login'
8	]
9	
10	function getCurrentPagePath() {
11		const pages = getCurrentPages ? getCurrentPages() : []
12		if (!pages || !pages.length) {
13			return ''
14		}
15		const top = pages[pages.length - 1]
16		return (top && top.route) || ''
17	}
18	
19	function ensureLogin(target) {
20		if (getToken()) {
21			return
22		}
23	
24		const path = target || getCurrentPagePath()
25		if (path && NO_AUTH_PAGES.indexOf(path) !== -1) {
26			return
27		}
28	
29		uni.reLaunch({ url: LOGIN_PAGE })
30	}
31	
32	export default {
33		onLaunch() {
34			ensureLogin()
