69					<button
70						class="btn-submit"
71						hover-class="btn-pressed"
72						:disabled="!reason.trim() || submitting"
73						@click="submitMakeup"
74					>{{ submitting ? '提交中...' : '提交补卡' }}</button>
75				</view>
76			</view>
77		</view>
78	</template>
79	
80	<script>
81	import { listResidentAttendance } from '../../services/attendance'
82	import { applyAndSubmitMakeup } from '../../services/record'
83	import { getResidentInfo } from '../../services/storage'
84	
85	export default {
86		data() {
87			return {
88				records: [],
89				selectedRecord: null,
90				reason: '',
91				loading: false,
92				submitting: false
93			}
94		},
95		onLoad() {
96			this.loadMissedRecords()
97		},
98		methods: {
99			async loadMissedRecords() {
100				const resident = getResidentInfo()
101				if (!resident || !resident.id) {
102					uni.showToast({ title: '请先登录', icon: 'none' })
103					return
104				}
105	
106				this.loading = true
107				try {
108					const now = new Date()
109					const start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString()
110					const end = now.toISOString()
111	
112					const result = await listResidentAttendance({
113						residentId: resident.id,
114						startDate: start,
115						endDate: end,
116						page: { pageNo: 1, pageSize: 50 }
117					})
118	
119					// 只显示缺勤(MISSED)和无效(INVALID)的记录
120					this.records = result.data.filter(
121						(item) => item.status === 'MISSED' || item.status === 'INVALID'
122					)
123				} catch (e) {
124					uni.showToast({ title: '加载失败', icon: 'none' })
125				} finally {
126					this.loading = false
127				}
128			},
129			selectRecord(item) {
130				this.selectedRecord = item
131				this.reason = ''
132			},
133			async submitMakeup() {
134				if (!this.reason.trim()) {
135					uni.showToast({ title: '请填写补卡原因', icon: 'none' })
136					return
137				}
138				if (this.submitting) return
139	
140				const resident = getResidentInfo()
141				if (!resident || !resident.id) return
142	
143				this.submitting = true
144				uni.showLoading({ title: '提交中...' })
145				try {
146					await applyAndSubmitMakeup({
147						residentId: resident.id,
148						targetAttendanceId: this.selectedRecord.id,
149						reason: this.reason.trim()
150					})
151					uni.hideLoading()
152					uni.showToast({ title: '补卡申请已提交', icon: 'success' })
153					setTimeout(() => uni.navigateBack(), 1500)
154				} catch (e) {
155					uni.hideLoading()
156					uni.showToast({ title: e.message || '提交失败', icon: 'none' })
157				} finally {
158					this.submitting = false
159				}
160			},
161			formatDate(dateStr) {
162				if (!dateStr) return '-'
163				const d = new Date(dateStr)
164				if (Number.isNaN(d.getTime())) return dateStr
165				const m = (d.getMonth() + 1).toString().padStart(2, '0')
166				const day = d.getDate().toString().padStart(2, '0')
167				const hh = d.getHours().toString().padStart(2, '0')
168				const mm = d.getMinutes().toString().padStart(2, '0')
169				return `${m}-${day} ${hh}:${mm}`
170			}
171		}
172	}
173	</script>
