81	import { OBJECT_TYPES } from '../../utils/api'
82	import { callPayloadAction, callIdAction } from '../../utils/request'
83	import { getResidentInfo } from '../../services/storage'
84	
85	const ADDRESS_TYPES = [
86		{ value: 'FIXED_WORKPLACE', label: '固定工作场所' },
87		{ value: 'FLEXIBLE_EMPLOYMENT', label: '灵活就业' },
88		{ value: 'MIGRANT_WORK', label: '外出务工' },
89		{ value: 'OTHER', label: '其他' }
90	]
