92	export default {
93		data() {
94			return {
95				address: '',
96				employer: '',
97				addressType: 'FIXED_WORKPLACE',
98				reason: '',
99				longitude: undefined,
100				latitude: undefined,
101				submitting: false,
102				addressTypes: ADDRESS_TYPES
103			}
104		},
105		computed: {
106			canSubmit() {
107				return this.address.trim() && this.employer.trim()
108			}
109		},
110		methods: {
111			pickLocation() {
112				uni.chooseLocation({
113					success: (res) => {
114						this.longitude = Number((res.longitude || 0).toFixed(6))
115						this.latitude = Number((res.latitude || 0).toFixed(6))
116						if (res.address || res.name) {
117							this.address = res.name && res.address && res.address.indexOf(res.name) === -1
118								? `${res.address} ${res.name}`
119								: (res.address || res.name)
120						}
121					},
122					fail: (err) => {
123						if (err && err.errMsg && err.errMsg.includes('cancel')) return
124						uni.showToast({ title: '选择地点失败', icon: 'none' })
125					}
126				})
127			},
128			async submit() {
129				if (!this.canSubmit || this.submitting) return
130	
131				const resident = getResidentInfo()
132				if (!resident || !resident.id) {
133					uni.showToast({ title: '请先登录', icon: 'none' })
134					return
135				}
136	
137				this.submitting = true
138				uni.showLoading({ title: '提交中...' })
139				try {
140					const companyAddress = {
141						detail: this.address,
142						...(this.longitude ? { geoPoint: { longitude: this.longitude, latitude: this.latitude } } : {})
143					}
144	
145					// add
146					const addRes = await callPayloadAction('add', OBJECT_TYPES.employmentChange, {
147						resident: resident.id,
148						companyAddress,
149						employer: this.employer,
150						addressType: this.addressType,
151						reason: this.reason || '',
152						status: 'DRAFT'
153					})
154	
155					const data = addRes && addRes.data
156					const id = Array.isArray(data) ? (data[0] && data[0].id) : (data && data.id)
157					if (!id) throw new Error('创建变更记录失败')
158	
159					// submit (重试一次)
160					try {
161						await callIdAction('submit', OBJECT_TYPES.employmentChange, id)
162					} catch (e) {
163						await callIdAction('submit', OBJECT_TYPES.employmentChange, id)
164					}
165	
166					uni.hideLoading()
167					uni.showToast({ title: '变更申请已提交', icon: 'success' })
168					setTimeout(() => uni.navigateBack(), 1500)
169				} catch (e) {
170					uni.hideLoading()
171					uni.showToast({ title: e.message || '提交失败', icon: 'none' })
172				} finally {
173					this.submitting = false
174				}
175			}
176		}
177	}
