76	<script>
77	import { uploadAttendanceAttachment, submitAttendance } from '../../services/attendance'
78	import { fetchResidentDetail } from '../../services/resident'
79	import { getResidentInfo, setResidentInfo } from '../../services/storage'
80	
81	const VERIFIED_STATUSES = ['VERIFIED', 'ACTIVATED']
82	
83	export default {
84		data() {
85			return {
86				photoList: [],
87				submitting: false,
88				verified: false,
89				checkingVerify: true
90			}
91		},
92		onLoad() {
93			this.ensureVerified()
94		},
95		onShow() {
96			if (!this.verified) {
97				this.ensureVerified()
98			}
99		},
100		methods: {
101			async ensureVerified() {
102				this.checkingVerify = true
103				try {
104					let resident = getResidentInfo()
105					if (resident && resident.id) {
106						try {
107							const fresh = await fetchResidentDetail(resident.id)
108							if (fresh) {
109								resident = fresh
110								setResidentInfo(fresh)
111							}
112						} catch (error) {
113							// 网络失败时退回本地缓存,继续按缓存状态校验
114						}
115					}
116	
117					// 非微信环境下跳过核身检查(人脸核身仅微信支持)
118					// #ifndef MP-WEIXIN
119					this.verified = !!(resident && resident.id)
120					// #endif
121					// #ifdef MP-WEIXIN
122					this.verified = !!(resident && resident.id && VERIFIED_STATUSES.indexOf(resident.status) !== -1)
123					// #endif
124				} finally {
125					this.checkingVerify = false
126				}
127			},
128			},
129			goVerify() {
130				// photo-capture 页是从 checkin navigateTo 进来的,直接 navigateBack 回核身页
131				const pages = getCurrentPages()
132				if (pages && pages.length > 1) {
133					uni.navigateBack()
134					return
135				}
136				uni.reLaunch({ url: '/pages/checkin/checkin' })
137			},
138			takePhoto() {
139				if (!this.verified) {
140					uni.showToast({ title: '请先完成身份核验', icon: 'none' })
141					return
142				}
143				uni.showActionSheet({
144					itemList: ['拍照', '从相册选择'],
145					success: (res) => {
146						const sourceType = res.tapIndex === 0 ? ['camera'] : ['album']
147						this.choosePhotos(sourceType)
148					}
149				})
150			},
151			choosePhotos(sourceType) {
152				uni.chooseImage({
153					count: 9 - this.photoList.length,
154					sizeType: ['compressed'],
155					sourceType,
156					success: (res) => {
157						const tempFilePaths = Array.isArray(res.tempFilePaths) ? res.tempFilePaths : []
158						this.photoList = this.photoList.concat(tempFilePaths).slice(0, 9)
159	
160						if (this.photoList.length >= 9) {
161							uni.showToast({ title: '最多上传9张照片', icon: 'none' })
162						}
163					},
164					fail: (err) => {
165						if (err && err.errMsg && err.errMsg.includes('cancel')) {
166							return
167						}
168						uni.showToast({ title: '选择照片失败', icon: 'none' })
169					}
170				})
171			},
172			deletePhoto(index) {
173				uni.showModal({
174					title: '提示',
175					content: '确定删除这张照片吗？',
176					success: (res) => {
177						if (res.confirm) {
178							this.photoList.splice(index, 1)
179						}
180					}
181				})
182			},
183			getLocation() {
184				return new Promise((resolve) => {
185					uni.getLocation({
186						type: 'gcj02',
187						success: (res) => resolve({
188							longitude: Number(res.longitude.toFixed(6)),
189							latitude: Number(res.latitude.toFixed(6))
190						}),
191						fail: () => resolve(null)
192					})
193				})
194			},
195			async submitCheckin() {
196				if (this.submitting) {
197					return
198				}
199	
200				if (!this.verified) {
201					uni.showToast({ title: '请先完成身份核验', icon: 'none' })
202					return
203				}
204	
205				if (this.photoList.length === 0) {
206					uni.showToast({ title: '请至少拍摄一张照片', icon: 'none' })
207					return
208				}
209	
210				const resident = getResidentInfo()
211				if (!resident || !resident.id) {
212					uni.showModal({
213						title: '请先登录',
214						content: '尚未识别到居民信息，请重新登录后再打卡。',
215						showCancel: false,
216						success: () => uni.navigateTo({ url: '/pages/login/login?from=checkin' })
217					})
218					return
219				}
220	
221				this.submitting = true
222				try {
223					const attachments = []
